-- ===== invoice-special-expanded-local.sql =====
-- LOCAL ONLY. Additive selective/alcohol/beverage tax extension; no historical recalculation or backfill.
-- Install after invoice-extras-local.sql. Legacy 03/06/12 input/read shapes and arithmetic remain unchanged.
begin;
alter table public.pro_invoice_edited_detail drop constraint if exists pro_invoice_edited_detail_calculation_version_check;
alter table public.pro_invoice_edited_detail add constraint pro_invoice_edited_detail_calculation_version_check check(calculation_version in ('crc-draft-v1','crc-draft-tax-v2','crc-draft-extras-v3','crc-draft-extras-v4'));
alter table public.pro_invoice_line_special_tax add column if not exists selective_base numeric;
alter table public.pro_invoice_line_special_tax add column if not exists selective_legal_reference text;
alter table public.pro_invoice_line_special_tax add column if not exists alcohol_percentage numeric;
alter table public.pro_invoice_line_special_tax add column if not exists beverage_kind text;
alter table public.pro_invoice_line_special_tax add column if not exists beverage_reference_volume numeric;
alter table public.pro_invoice_line_special_tax drop constraint if exists pro_invoice_line_special_tax_tax_number_check;
alter table public.pro_invoice_line_special_tax add constraint pro_invoice_line_special_tax_tax_number_check check(tax_number between 1 and 6);
alter table public.pro_invoice_line_special_tax drop constraint if exists pro_invoice_line_special_tax_code_check;
alter table public.pro_invoice_line_special_tax add constraint pro_invoice_line_special_tax_code_check check(code in ('02','03','04','05','06','12'));
alter table public.pro_invoice_line_special_tax drop constraint if exists pro_invoice_line_special_tax_check;
alter table public.pro_invoice_line_special_tax drop constraint if exists pro_invoice_line_special_tax_shape_v4;
alter table public.pro_invoice_line_special_tax add constraint pro_invoice_line_special_tax_shape_v4 check(
 (code='12' and rate is not null and rate>0 and rate<=100 and rate=round(rate,2) and quantity_per_unit is null and amount_per_unit is null and num_nonnulls(selective_base,selective_legal_reference,alcohol_percentage,beverage_kind,beverage_reference_volume)=0)
 or (code in ('03','06') and rate is null and quantity_per_unit is not null and quantity_per_unit>0 and quantity_per_unit<=99999.99 and quantity_per_unit=round(quantity_per_unit,2) and amount_per_unit is not null and amount_per_unit>0 and amount_per_unit<=100000000 and amount_per_unit=round(amount_per_unit,5) and num_nonnulls(selective_base,selective_legal_reference,alcohol_percentage,beverage_kind,beverage_reference_volume)=0)
 or (code='02' and rate is not null and rate>0 and rate<=99.99 and rate=round(rate,2) and quantity_per_unit is null and amount_per_unit is null and selective_base is not null and selective_base>0 and selective_base<=100000000 and selective_base=round(selective_base,5) and selective_legal_reference is not null and length(trim(selective_legal_reference)) between 5 and 160 and num_nonnulls(alcohol_percentage,beverage_kind,beverage_reference_volume)=0)
 or (code='04' and rate is null and quantity_per_unit is not null and quantity_per_unit>0 and quantity_per_unit<=99999.99 and quantity_per_unit=round(quantity_per_unit,2) and amount_per_unit is not null and amount_per_unit>0 and amount_per_unit<=100000000 and amount_per_unit=round(amount_per_unit,5) and alcohol_percentage is not null and alcohol_percentage>0 and alcohol_percentage<=99.99 and alcohol_percentage=round(alcohol_percentage,2) and num_nonnulls(selective_base,selective_legal_reference,beverage_kind,beverage_reference_volume)=0)
 or (code='05' and rate is null and quantity_per_unit is not null and quantity_per_unit>0 and quantity_per_unit<=99999.99 and quantity_per_unit=round(quantity_per_unit,2) and amount_per_unit is not null and amount_per_unit>0 and amount_per_unit<=100000000 and amount_per_unit=round(amount_per_unit,5) and beverage_kind is not null and beverage_kind='beverage' and beverage_reference_volume is not null and beverage_reference_volume>0 and beverage_reference_volume<=99999.99 and beverage_reference_volume=round(beverage_reference_volume,2) and num_nonnulls(selective_base,selective_legal_reference,alcohol_percentage)=0)
);
create or replace function public.pro_invoice_extras_totals(p_user uuid,p_id uuid) returns table(gross_tax numeric,exonerated numeric,special_tax numeric,charge_total numeric)
language sql stable security invoker set search_path=public,pg_temp as $$
 with gross_lines as (select l.*,round(quantity*unit_price,5) as gross from pro_invoice_edited_lines l where user_id=p_user and draft_id=p_id),
 bases as (select *,gross-case when discount_type='percent' then round(gross*discount/100,5) else discount end as net from gross_lines),
 -- Beverage division uses integer numeric units: div(2*N+D,2*D) avoids an intermediate numeric quotient rounding across a half-unit boundary.
 specials as (select t.line_number,t.code,case t.code when '02' then round(t.selective_base*t.rate/100,5) when '04' then round(b.quantity*round(t.quantity_per_unit*t.alcohol_percentage/100,5)*t.amount_per_unit,5) when '05' then round(div(2*((b.quantity*100000)*(t.quantity_per_unit*100000)*(t.amount_per_unit*100000))+(t.beverage_reference_volume*10000000000),2*(t.beverage_reference_volume*10000000000))/100000,5) when '12' then round(b.net*t.rate/100,5) when '03' then round(t.quantity_per_unit*t.amount_per_unit,5) when '06' then round(b.quantity*t.quantity_per_unit*t.amount_per_unit,5) end as amount from pro_invoice_line_special_tax t join bases b using(user_id,draft_id,line_number)),
 taxed as (select b.*,t.exemption_rate,b.net+coalesce((select sum(s.amount) from specials s where s.line_number=b.line_number and s.code in ('02','04','05','12')),0) as vat_base from bases b left join pro_invoice_line_tax t using(user_id,draft_id,line_number))
 select coalesce((select sum(case when tax_treatment='vat' then round(vat_base*tax_rate/100,5) else 0 end) from taxed),0),
 coalesce((select sum(case when exemption_rate is not null then round(vat_base*exemption_rate/100,5) else 0 end) from taxed),0),
 coalesce((select sum(amount) from specials),0),
 coalesce((select sum(case mode when 'amount' then value else round(base*value/100,5) end) from pro_invoice_draft_charges where user_id=p_user and draft_id=p_id),0);
$$;
create or replace function public.pro_invoice_extras_read(p_user uuid,p_id uuid,p_after jsonb default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare document jsonb;lines jsonb;charges jsonb;totals record;
begin
 document:=pro_invoice_tax_read(p_user,p_id,p_after);
 if document is null or not(exists(select 1 from pro_invoice_line_special_tax where user_id=p_user and draft_id=p_id) or exists(select 1 from pro_invoice_draft_charges where user_id=p_user and draft_id=p_id)) then return document;end if;
 select coalesce(jsonb_agg(jsonb_build_object('code',code,'otherDetail',other_detail,'description',description,'mode',mode,'value',value::text,'base',coalesce(base::text,''),'thirdParty',case when third_party_id_type is null then null else jsonb_build_object('idType',third_party_id_type,'id',third_party_id,'name',third_party_name) end) order by charge_number),'[]'::jsonb) into charges from pro_invoice_draft_charges where user_id=p_user and draft_id=p_id;
 document:=document||jsonb_build_object('charges',charges);
 if document->'editedDetail' is null or document->'editedDetail'='null'::jsonb then return document;end if;
 select jsonb_agg(e.value||case when e.value ? 'tax' then '{}'::jsonb else jsonb_build_object('tax',null) end||jsonb_build_object('specialTaxes',coalesce((select jsonb_agg(jsonb_build_object('code',s.code,'rate',coalesce(s.rate::text,''),'quantityPerUnit',coalesce(s.quantity_per_unit::text,''),'amountPerUnit',coalesce(s.amount_per_unit::text,''))||case s.code when '02' then jsonb_build_object('selective',jsonb_build_object('base',s.selective_base::text,'legalReference',s.selective_legal_reference)) when '04' then jsonb_build_object('alcohol',jsonb_build_object('percentage',s.alcohol_percentage::text)) when '05' then jsonb_build_object('beverage',jsonb_build_object('kind',s.beverage_kind,'referenceVolume',s.beverage_reference_volume::text)) else '{}'::jsonb end order by tax_number) from pro_invoice_line_special_tax s where s.user_id=p_user and s.draft_id=p_id and s.line_number=e.n),'[]'::jsonb)) order by e.n) into lines from jsonb_array_elements(document->'editedDetail'->'lines') with ordinality e(value,n);
 select * into totals from pro_invoice_extras_totals(p_user,p_id);
 return jsonb_set(document,'{editedDetail}',document->'editedDetail'||jsonb_build_object('lines',lines,'grossTax',round(totals.gross_tax,5)::text,'exonerated',round(totals.exonerated,5)::text,'specialTax',round(totals.special_tax,5)::text,'chargeTotal',round(totals.charge_total,5)::text,'version',case when exists(select 1 from pro_invoice_line_special_tax where user_id=p_user and draft_id=p_id and code in ('02','04','05')) then 'crc-draft-extras-v4' else 'crc-draft-extras-v3' end));
end $$;
create or replace function public.pro_invoice_extras_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare saved uuid;target uuid;action text:=p_input->>'action';line record;special record;charge record;third jsonb;totals record;old_charges numeric;has_extras boolean;has_vat boolean;had_detail boolean;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if action='create_direct' then
  target:=(p_input->>'requestId')::uuid;
  if exists(select 1 from pro_invoice_drafts where user_id=p_user and id=target) then return pro_invoice_tax_save(p_user,p_input);end if;
 elsif action in ('detail','refresh','reset_detail','update') then target:=(p_input->>'id')::uuid;end if;
 if action='detail' then
  if exists(select 1 from pro_invoice_line_special_tax where user_id=p_user and draft_id=target) and exists(select 1 from jsonb_array_elements(p_input->'lines') e where not(e ? 'specialTaxes')) then raise exception 'This editor cannot preserve saved special taxes; reload' using errcode='40001';end if;
  if exists(select 1 from pro_invoice_draft_charges where user_id=p_user and draft_id=target) and not(p_input ? 'charges') then raise exception 'This editor cannot preserve saved charges; reload' using errcode='40001';end if;
 end if;
 -- A reset leaves charges independent of the edited detail. Never feed them back into a source snapshot.
 if action in ('detail','refresh') and not exists(select 1 from pro_invoice_edited_detail where user_id=p_user and draft_id=target) then
  select charge_total into old_charges from pro_invoice_extras_totals(p_user,target);
  if old_charges>0 then update pro_invoice_drafts set total_cents=total_cents-round(old_charges*100) where user_id=p_user and id=target;end if;
 end if;
 select exists(select 1 from pro_invoice_edited_detail where user_id=p_user and draft_id=target) into had_detail;
 saved:=pro_invoice_tax_save(p_user,p_input);
 if action='reset_detail' and not had_detail then return saved;end if;
 if action in ('detail','create_direct') then
  for line in select value,n from jsonb_array_elements(p_input->'lines') with ordinality e(value,n) loop
   if not(line.value ? 'specialTaxes') then continue;end if;
   if jsonb_typeof(line.value->'specialTaxes') is distinct from 'array' or jsonb_array_length(line.value->'specialTaxes')>6 then raise exception 'Invalid special taxes' using errcode='22023';end if;
   for special in select value,n from jsonb_array_elements(line.value->'specialTaxes') with ordinality e(value,n) loop
    if ((special.value ? 'selective') and special.value->>'code'<>'02') or ((special.value ? 'alcohol') and special.value->>'code'<>'04') or ((special.value ? 'beverage') and special.value->>'code'<>'05') then raise exception 'Unexpected special-tax fields' using errcode='22023';end if;
    if (special.value->>'code'='02' and jsonb_typeof(special.value->'selective') is distinct from 'object') or (special.value->>'code'='04' and jsonb_typeof(special.value->'alcohol') is distinct from 'object') or (special.value->>'code'='05' and jsonb_typeof(special.value->'beverage') is distinct from 'object') then raise exception 'Missing special-tax basis' using errcode='22023';end if;
    insert into pro_invoice_line_special_tax(user_id,draft_id,line_number,tax_number,code,rate,quantity_per_unit,amount_per_unit,selective_base,selective_legal_reference,alcohol_percentage,beverage_kind,beverage_reference_volume) values(p_user,saved,line.n,special.n,special.value->>'code',replace(nullif(special.value->>'rate',''),',','.')::numeric,replace(nullif(special.value->>'quantityPerUnit',''),',','.')::numeric,replace(nullif(special.value->>'amountPerUnit',''),',','.')::numeric,replace(nullif(special.value->'selective'->>'base',''),',','.')::numeric,special.value->'selective'->>'legalReference',replace(nullif(special.value->'alcohol'->>'percentage',''),',','.')::numeric,special.value->'beverage'->>'kind',replace(nullif(special.value->'beverage'->>'referenceVolume',''),',','.')::numeric);
   end loop;
  end loop;
  if p_input ? 'charges' then
   if jsonb_typeof(p_input->'charges') is distinct from 'array' or jsonb_array_length(p_input->'charges')>15 then raise exception 'Invalid charges' using errcode='22023';end if;
   delete from pro_invoice_draft_charges where user_id=p_user and draft_id=saved;
   for charge in select value,n from jsonb_array_elements(p_input->'charges') with ordinality e(value,n) loop
    third:=charge.value->'thirdParty';
    if third is null or (third<>'null'::jsonb and jsonb_typeof(third)<>'object') then raise exception 'Invalid third party' using errcode='22023';end if;
    insert into pro_invoice_draft_charges(user_id,draft_id,charge_number,code,other_detail,description,mode,value,base,third_party_id_type,third_party_id,third_party_name) values(p_user,saved,charge.n,charge.value->>'code',charge.value->>'otherDetail',charge.value->>'description',charge.value->>'mode',replace(charge.value->>'value',',','.')::numeric,replace(nullif(charge.value->>'base',''),',','.')::numeric,third->>'idType',third->>'id',third->>'name');
   end loop;
  end if;
 end if;
 -- Updates only change receiver/preparation/title; their already adjusted totals remain untouched.
 if action in ('detail','create_direct','refresh','reset_detail') then
  select * into totals from pro_invoice_extras_totals(p_user,saved);
  select exists(select 1 from pro_invoice_line_special_tax where user_id=p_user and draft_id=saved) or exists(select 1 from pro_invoice_draft_charges where user_id=p_user and draft_id=saved) into has_extras;
  select exists(select 1 from pro_invoice_line_tax where user_id=p_user and draft_id=saved) into has_vat;
  if exists(select 1 from pro_invoice_edited_detail where user_id=p_user and draft_id=saved) then
   if exists(select 1 from pro_invoice_edited_detail where user_id=p_user and draft_id=saved and round((net+totals.gross_tax+totals.special_tax+totals.charge_total)*100)>10000000000) then raise exception 'Draft before-exoneration total exceeds limit' using errcode='22023';end if;
   update pro_invoice_edited_detail set tax=totals.gross_tax-totals.exonerated,total=net+totals.gross_tax-totals.exonerated+totals.special_tax+totals.charge_total,calculation_version=case when exists(select 1 from pro_invoice_line_special_tax where user_id=p_user and draft_id=saved and code in ('02','04','05')) then 'crc-draft-extras-v4' when has_extras then 'crc-draft-extras-v3' when has_vat then 'crc-draft-tax-v2' else 'crc-draft-v1' end where user_id=p_user and draft_id=saved;
   update pro_invoice_drafts d set total_cents=round(h.total*100),tax_cents=round((h.tax+totals.special_tax)*100) from pro_invoice_edited_detail h where h.user_id=p_user and h.draft_id=saved and d.user_id=h.user_id and d.id=h.draft_id;
  elsif totals.charge_total>0 then
   -- The legacy refresh/reset restored the source amount. Its tax NULL remains unknown, not invented zero.
   update pro_invoice_drafts set total_cents=total_cents+round(totals.charge_total*100) where user_id=p_user and id=saved;
  end if;
 end if;
 return saved;
end $$;
revoke all on function public.pro_invoice_extras_totals(uuid,uuid),public.pro_invoice_extras_read(uuid,uuid,jsonb),public.pro_invoice_extras_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_invoice_extras_totals(uuid,uuid),public.pro_invoice_extras_read(uuid,uuid,jsonb),public.pro_invoice_extras_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== catalog-item-types-local.sql =====
-- LOCAL ONLY: additive item type, without reclassifying or rewriting existing records.
begin;
alter table public.pro_products add column if not exists "itemType" text;
do $$ begin
 if not exists(select 1 from pg_constraint where conrelid='pro_products'::regclass and conname='pro_products_item_type_valid') then
 alter table pro_products add constraint pro_products_item_type_valid check("itemType" is null or "itemType" in ('product','service'));
 end if;
 if not exists(select 1 from pg_constraint where conrelid='pro_products'::regclass and conname='pro_products_service_no_stock') then
 alter table pro_products add constraint pro_products_service_no_stock check("itemType" is distinct from 'service' or stock=0 and minimum=0);
 end if;
end $$;
create index if not exists pro_products_type_page on pro_products(user_id,coalesce("itemType",'product'),archived,id);
create or replace function public.pro_upsert_catalog(p_user uuid,p_document jsonb) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 insert into pro_clients(user_id,"id","name","email","phone","notes","archived","identification","tradeName","group","address")
 select p_user,"id","name","email","phone","notes","archived","identification","tradeName","group","address" from jsonb_to_recordset(coalesce(p_document->'clients','[]')) as r("id" text,"name" text,"email" text,"phone" text,"notes" text,"archived" boolean,"identification" text,"tradeName" text,"group" text,"address" text)
 on conflict(user_id,id) do update set
 "name"=excluded."name","email"=excluded."email","phone"=excluded."phone","notes"=excluded."notes","archived"=excluded."archived","identification"=excluded."identification","tradeName"=excluded."tradeName","group"=excluded."group","address"=excluded."address"
 where (to_jsonb(pro_clients)-'position') is distinct from (to_jsonb(excluded)-'position');
 insert into pro_products(user_id,"id","sku","name","stock","minimum","cost","price","archived","category","unit","cabys","itemType")
 select p_user,"id","sku","name","stock","minimum","cost","price","archived","category","unit","cabys","itemType" from jsonb_to_recordset(coalesce(p_document->'products','[]')) as r("id" text,"sku" text,"name" text,"stock" numeric,"minimum" numeric,"cost" numeric,"price" numeric,"archived" boolean,"category" text,"unit" text,"cabys" text,"itemType" text)
 on conflict(user_id,id) do update set
 "sku"=excluded."sku","name"=excluded."name","stock"=excluded."stock","minimum"=excluded."minimum","cost"=excluded."cost","price"=excluded."price","archived"=excluded."archived","category"=excluded."category","unit"=excluded."unit","cabys"=excluded."cabys","itemType"=coalesce(excluded."itemType",pro_products."itemType")
 where (to_jsonb(pro_products)-'position') is distinct from (to_jsonb(excluded)-'position');
 insert into pro_movements(user_id,"id","productId","delta","reason","at")
 select p_user,"id","productId","delta","reason","at" from jsonb_to_recordset(coalesce(p_document->'movements','[]')) as r("id" text,"productId" text,"delta" numeric,"reason" text,"at" text)
 on conflict(user_id,id) do update set
 "productId"=excluded."productId","delta"=excluded."delta","reason"=excluded."reason","at"=excluded."at"
 where (to_jsonb(pro_movements)-'position') is distinct from (to_jsonb(excluded)-'position');
end $$;

create or replace function public.pro_keep_catalog_type() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='UPDATE' then
  -- Null is how pre-discriminator writers represent omission. Preserve an existing explicit type.
  if new."itemType" is null then new."itemType":=old."itemType";end if;
  if coalesce(new."itemType",'product')<>coalesce(old."itemType",'product') then raise exception 'Catalog item type is immutable' using errcode='22023';end if;
 end if;
 if new."itemType"='service' and (new.stock<>0 or new.minimum<>0) then raise exception 'Services have no stock' using errcode='22023';end if;
 return new;
end $$;
drop trigger if exists pro_keep_catalog_type on pro_products;
create trigger pro_keep_catalog_type before insert or update on pro_products for each row execute function pro_keep_catalog_type();
create or replace function public.pro_require_stock_item() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare item text;
begin
 if tg_table_name='pro_movements' then item:=new."productId";else item:=new.product_id;end if;
 if item is not null and exists(select 1 from pro_products where user_id=new.user_id and id=item and "itemType"='service') then raise exception 'A service cannot reference stock' using errcode='22023';end if;
 return new;
end $$;
drop trigger if exists pro_require_stock_item on pro_movements;
create trigger pro_require_stock_item before insert or update on pro_movements for each row execute function pro_require_stock_item();
-- On a fresh preparation invoice tables appear later; the preparer reapplies this file at the end.
do $$ begin
 if to_regclass('public.pro_invoice_edited_lines') is not null then
 execute 'drop trigger if exists pro_require_stock_item on pro_invoice_edited_lines';
 execute 'create trigger pro_require_stock_item before insert or update on pro_invoice_edited_lines for each row execute function pro_require_stock_item()';
 end if;
end $$;
revoke all on function pro_keep_catalog_type(),pro_require_stock_item(),pro_upsert_catalog(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_keep_catalog_type(),pro_require_stock_item(),pro_upsert_catalog(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== catalog-organizations-local.sql =====
-- LOCAL ONLY. Independent taxonomy; never rewrites catalog text or workspace JSON.
begin;
create table if not exists public.pro_catalog_organization_revisions (
 user_id uuid references public.profiles(id) on delete cascade,kind text check(kind in ('client_group','product_category')),revision integer not null default 0 check(revision>=0),primary key(user_id,kind)
);
create table if not exists public.pro_catalog_organizations (
 user_id uuid references public.profiles(id) on delete cascade,kind text check(kind in ('client_group','product_category')),id uuid not null,name text not null check(name=btrim(name) and length(name) between 1 and 80),archived boolean not null default false,position bigint generated always as identity,primary key(user_id,kind,id)
);
create table if not exists public.pro_catalog_organization_aliases (
 user_id uuid not null,kind text not null,organization_id uuid not null,name text not null check(length(name) between 1 and 80),name_key text generated always as (lower(btrim(name))) stored,primary key(user_id,kind,name_key),foreign key(user_id,kind,organization_id) references public.pro_catalog_organizations(user_id,kind,id) on delete cascade
);
create index if not exists pro_clients_organization_text on public.pro_clients(user_id,lower(btrim("group")));
create index if not exists pro_products_organization_text on public.pro_products(user_id,lower(btrim(category)));
create index if not exists pro_catalog_organizations_page on public.pro_catalog_organizations(user_id,kind,archived,position);
create index if not exists pro_catalog_organization_alias_owner on public.pro_catalog_organization_aliases(user_id,kind,organization_id);
alter table public.pro_catalog_organization_revisions enable row level security;
alter table public.pro_catalog_organizations enable row level security;
alter table public.pro_catalog_organization_aliases enable row level security;
drop policy if exists own_read on public.pro_catalog_organizations;
create policy own_read on public.pro_catalog_organizations for select to authenticated using(user_id=auth.uid());
drop policy if exists own_read on public.pro_catalog_organization_aliases;
create policy own_read on public.pro_catalog_organization_aliases for select to authenticated using(user_id=auth.uid());
drop policy if exists own_read on public.pro_catalog_organization_revisions;
create policy own_read on public.pro_catalog_organization_revisions for select to authenticated using(user_id=auth.uid());
revoke all on public.pro_catalog_organizations,public.pro_catalog_organization_aliases,public.pro_catalog_organization_revisions from public,anon,authenticated;
grant select on public.pro_catalog_organizations,public.pro_catalog_organization_aliases,public.pro_catalog_organization_revisions to authenticated;
grant all on public.pro_catalog_organizations,public.pro_catalog_organization_aliases,public.pro_catalog_organization_revisions to service_role;
grant usage,select on sequence public.pro_catalog_organizations_position_seq to service_role;
create or replace function public.pro_mutate_catalog_organization(p_user uuid,p_kind text,p_action text,p_id uuid,p_name text,p_revision integer) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r integer;existing public.pro_catalog_organizations;clean text=btrim(p_name);
begin
 if p_user is null or p_kind is null or p_kind not in ('client_group','product_category') or p_action is null or p_action not in ('create','rename','archive','restore') or p_id is null or p_revision is null or p_revision<0 then raise exception 'Invalid operation' using errcode='22023';end if;
 if p_action in ('create','rename') and (clean is null or length(clean) not between 1 and 80) then raise exception 'Invalid name' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 insert into pro_catalog_organization_revisions(user_id,kind) values(p_user,p_kind) on conflict do nothing;
 select revision into r from pro_catalog_organization_revisions where user_id=p_user and kind=p_kind for update;
 if r<>p_revision then raise exception 'Stale organization revision' using errcode='40001';end if;
 select * into existing from pro_catalog_organizations where user_id=p_user and kind=p_kind and id=p_id;
 if p_action='create' then
  insert into pro_catalog_organizations(user_id,kind,id,name) values(p_user,p_kind,p_id,clean);
 elsif existing.id is null then raise exception 'Unknown organization' using errcode='P0002';
 elsif p_action='rename' then update pro_catalog_organizations set name=clean where user_id=p_user and kind=p_kind and id=p_id;
 else update pro_catalog_organizations set archived=(p_action='archive') where user_id=p_user and kind=p_kind and id=p_id;
 end if;
 if p_action in ('create','rename') then
  if exists(select 1 from pro_catalog_organization_aliases where user_id=p_user and kind=p_kind and name_key=lower(clean) and organization_id<>p_id) then raise exception 'Reserved name' using errcode='23505';end if;
  insert into pro_catalog_organization_aliases(user_id,kind,organization_id,name) values(p_user,p_kind,p_id,clean) on conflict(user_id,kind,name_key) do nothing;
 end if;
 update pro_catalog_organization_revisions set revision=r+1 where user_id=p_user and kind=p_kind;return r+1;
end $$;
create or replace function public.pro_catalog_organization_page(p_user uuid,p_kind text,p_archived boolean default false,p_search text default '',p_after text default '',p_existing boolean default false) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare result jsonb;r integer;
begin
 if p_kind not in ('client_group','product_category') or p_kind is null or p_user is null or length(p_search)>160 or length(p_after)>160 or (not p_existing and p_after<>'' and p_after!~'^[0-9]{1,18}$') then raise exception 'Invalid query' using errcode='22023';end if;
 select coalesce((select revision from pro_catalog_organization_revisions where user_id=p_user and kind=p_kind),0) into r;
 if p_existing then
  with labels as (select "group" as name from pro_clients where user_id=p_user and p_kind='client_group' union all select category from pro_products where user_id=p_user and p_kind='product_category'),grouped as (
   select lower(btrim(name)) as key,min(name collate "C") as name,count(*) as n from labels where btrim(coalesce(name,''))<>'' and length(name)<=80 group by lower(btrim(name))
  ), page as (select * from grouped g where g.key>p_after collate "C" and not exists(select 1 from pro_catalog_organization_aliases a where a.user_id=p_user and a.kind=p_kind and a.name_key=g.key) and strpos(pro_catalog_search(g.name collate "default"),pro_catalog_search(p_search))>0 order by g.key collate "C" limit 21)
  select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('name',name,'recordCount',n) order by key collate "C") from (select * from page order by key collate "C" limit 20) x),'[]'::jsonb),'nextCursor',case when count(*)>20 then (select key from page order by key collate "C" offset 19 limit 1) else null end,'revision',r) into result from page;
 else
  with page as (select o.* from pro_catalog_organizations o where user_id=p_user and kind=p_kind and archived=p_archived and position>coalesce(nullif(p_after,''),'0')::bigint and (strpos(pro_catalog_search(name),pro_catalog_search(p_search))>0 or exists(select 1 from pro_catalog_organization_aliases a where a.user_id=p_user and a.kind=p_kind and a.organization_id=o.id and strpos(pro_catalog_search(a.name),pro_catalog_search(p_search))>0)) order by position limit 21),rows as (
   select p.*, (select count(*) from pro_catalog_organization_aliases a where a.user_id=p_user and a.kind=p_kind and a.organization_id=p.id) aliases,
   (select count(*) from (select "group" as label from pro_clients where user_id=p_user and p_kind='client_group' union all select category from pro_products where user_id=p_user and p_kind='product_category') c where exists(select 1 from pro_catalog_organization_aliases a where a.user_id=p_user and a.kind=p_kind and a.organization_id=p.id and a.name_key=lower(btrim(c.label)))) records from page p order by position limit 20)
  select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name,'archived',archived,'aliasCount',aliases,'recordCount',records) order by position) from rows),'[]'::jsonb),'nextCursor',case when count(*)>20 then (select position::text from rows order by rows.position desc limit 1) else null end,'revision',r) into result from page;
 end if;return result;
end $$;
revoke all on function public.pro_mutate_catalog_organization(uuid,text,text,uuid,text,integer),public.pro_catalog_organization_page(uuid,text,boolean,text,text,boolean) from public,anon,authenticated;
grant execute on function public.pro_mutate_catalog_organization(uuid,text,text,uuid,text,integer),public.pro_catalog_organization_page(uuid,text,boolean,text,text,boolean) to service_role;
commit;

-- ===== invoice-document-settings-local.sql =====
-- LOCAL ONLY. Future-draft defaults; no historical updates, numbering or fiscal issuance.
begin;
create table if not exists public.pro_invoice_document_settings(
 user_id uuid primary key references profiles(id) on delete cascade,
 sale_condition text not null check(sale_condition in ('','cash','credit')),
 credit_days integer not null check(credit_days between 0 and 3650),
 payment_method text not null check(payment_method in ('','cash','card','transfer','sinpe','other')),
 date_mode text not null check(date_mode in ('blank','today')),
 notes text not null check(length(notes)<=2000),
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default now(),
 check((sale_condition='credit' and credit_days>=1 and date_mode='today') or (sale_condition<>'credit' and credit_days=0))
);
alter table pro_invoice_document_settings enable row level security;
drop policy if exists pro_invoice_document_settings_owner on pro_invoice_document_settings;
create policy pro_invoice_document_settings_owner on pro_invoice_document_settings for select to authenticated using(user_id=auth.uid());
revoke all on pro_invoice_document_settings from public,anon,authenticated;
grant select on pro_invoice_document_settings to authenticated;
grant all on pro_invoice_document_settings to service_role;
create or replace function public.pro_invoice_document_settings_read(p_user uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select jsonb_build_object('revision',revision,'defaults',jsonb_build_object('saleCondition',sale_condition,'creditDays',credit_days,'paymentMethod',payment_method,'dateMode',date_mode,'notes',notes)) from pro_invoice_document_settings where user_id=p_user),jsonb_build_object('revision',0,'defaults',jsonb_build_object('saleCondition','','creditDays',0,'paymentMethod','','dateMode','blank','notes','')));
$$;
create or replace function public.pro_invoice_document_settings_save(p_user uuid,p_revision integer,p_defaults jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_revision integer;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select revision into v_revision from pro_invoice_document_settings where user_id=p_user for update;
 if p_revision is null or p_revision<0 or coalesce(v_revision,0)<>p_revision then raise exception 'Document settings changed' using errcode='40001';end if;
 insert into pro_invoice_document_settings(user_id,sale_condition,credit_days,payment_method,date_mode,notes)
 values(p_user,p_defaults->>'saleCondition',(p_defaults->>'creditDays')::integer,p_defaults->>'paymentMethod',p_defaults->>'dateMode',p_defaults->>'notes')
 on conflict(user_id) do update set sale_condition=excluded.sale_condition,credit_days=excluded.credit_days,payment_method=excluded.payment_method,date_mode=excluded.date_mode,notes=excluded.notes,revision=pro_invoice_document_settings.revision+1,updated_at=now();
 return pro_invoice_document_settings_read(p_user);
end $$;
-- Replaces the existing issuer hook without renaming/stacking wrappers. Reinstall is deterministic.
create or replace function public.pro_invoice_configured_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare existing uuid;saved uuid;config jsonb;defaults jsonb;d pro_invoice_drafts;prep jsonb;v_today text;fallback_name text;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if p_input->>'action'='create_direct' then select id into existing from pro_invoice_drafts where user_id=p_user and id=(p_input->>'requestId')::uuid;
 elsif p_input->>'action'='create' then existing:=(pro_invoice_source(p_user,p_input->>'kind',p_input->>'sourceId')->>'existingId')::uuid;end if;
 saved:=pro_invoice_direct_save(p_user,p_input);
 if existing is not null or p_input->>'action' not in ('create','create_direct') or p_input ? 'preparation' then return saved;end if;
 config:=pro_invoice_issuer_read(p_user);defaults:=pro_invoice_document_settings_read(p_user);
 -- Round 7A: without saved issuer settings a new DIRECT draft (also «Bill from job») starts with the company
 -- (business) name, then the account name, like «prepare from source» already proposes in its form; editable.
 if (config->>'revision')::integer=0 and p_input->>'action'='create_direct' then
  select left(coalesce(nullif(btrim(p.business_name),''),nullif(btrim(f.full_name),''),''),160) into fallback_name
   from profiles f left join professionals p on p.profile_id=f.id where f.id=p_user order by p.id limit 1;
  if coalesce(fallback_name,'')<>'' then config:=jsonb_set(config,'{issuer,issuerName}',to_jsonb(fallback_name));end if;
 end if;
 if (config->>'revision')::integer=0 and coalesce(config->'issuer'->>'issuerName','')='' and (defaults->>'revision')::integer=0 then return saved;end if;
 select * into d from pro_invoice_drafts where user_id=p_user and id=saved;
 v_today:=((now() at time zone 'America/Costa_Rica')::date)::text;
 prep:=(config->'issuer')||jsonb_build_object('plannedDate',case when defaults->'defaults'->>'dateMode'='today' then v_today else '' end,'saleCondition',defaults->'defaults'->>'saleCondition','creditDays',(defaults->'defaults'->>'creditDays')::integer,'paymentMethod',defaults->'defaults'->>'paymentMethod','orderReference','');
 -- Notes are entered/previewed by the client. An explicitly cleared note stays cleared.
 perform pro_invoice_full_save(p_user,jsonb_build_object('action','update','id',saved,'revision',d.revision,'title',d.title,'notes',d.notes,'receiver',jsonb_build_object('name',d.receiver_name,'identification',d.receiver_identification,'email',d.receiver_email,'phone',d.receiver_phone,'address',d.receiver_address),'preparation',prep));
 return saved;
end $$;
revoke all on function pro_invoice_document_settings_read(uuid),pro_invoice_document_settings_save(uuid,integer,jsonb),pro_invoice_configured_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_document_settings_read(uuid),pro_invoice_document_settings_save(uuid,integer,jsonb),pro_invoice_configured_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== invoice-management-local.sql =====
-- LOCAL ONLY. Archive flags and exact independent copies; no backfill, deletion or issuance.
-- Install after the complete invoice stack. Header trigger survives writer reinstallation.
begin;
create table if not exists public.pro_invoice_draft_management(
 user_id uuid not null,draft_id uuid not null,archived boolean not null default false,
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default now(),
 primary key(user_id,draft_id),foreign key(user_id,draft_id) references pro_invoice_drafts(user_id,id) on delete cascade
);
create table if not exists public.pro_invoice_draft_copies(
 user_id uuid not null,request_id uuid not null,source_id uuid not null,input_hash text not null,
 primary key(user_id,request_id),foreign key(user_id,request_id) references pro_invoice_drafts(user_id,id) on delete cascade,
 foreign key(user_id,source_id) references pro_invoice_drafts(user_id,id) on delete cascade
);
-- Metadata must not block the existing account-deletion cascade. Reinstall also
-- upgrades already-created local tables; no draft or snapshot is deleted here.
alter table public.pro_invoice_draft_copies drop constraint if exists pro_invoice_draft_copies_user_id_source_id_fkey;
alter table public.pro_invoice_draft_copies add constraint pro_invoice_draft_copies_user_id_source_id_fkey foreign key(user_id,source_id) references public.pro_invoice_drafts(user_id,id) on delete cascade;
-- An archive obtains the same owner lock and header row lock as edits. A waiting
-- edit observes the committed archive before its first header update can commit.
create or replace function public.pro_invoice_active_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if exists(select 1 from pro_invoice_draft_management where user_id=old.user_id and draft_id=old.id and archived) then raise exception 'Restore archived draft before editing' using errcode='22023';end if;
 return new;
end $$;
drop trigger if exists pro_invoice_active_guard on pro_invoice_drafts;
create trigger pro_invoice_active_guard before update on pro_invoice_drafts for each row execute function pro_invoice_active_guard();
alter table pro_invoice_draft_management enable row level security;
alter table pro_invoice_draft_copies enable row level security;
drop policy if exists pro_invoice_management_owner on pro_invoice_draft_management;
drop policy if exists pro_invoice_copies_owner on pro_invoice_draft_copies;
create policy pro_invoice_management_owner on pro_invoice_draft_management for select to authenticated using(user_id=(select auth.uid()));
create policy pro_invoice_copies_owner on pro_invoice_draft_copies for select to authenticated using(user_id=(select auth.uid()));
revoke all on pro_invoice_draft_management,pro_invoice_draft_copies from public,anon,authenticated;
grant select on pro_invoice_draft_management,pro_invoice_draft_copies to authenticated;
grant all on pro_invoice_draft_management,pro_invoice_draft_copies to service_role;
create or replace function public.pro_invoice_management_read(p_user uuid,p_id uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',d.id,'revision',d.revision,'managementRevision',coalesce(m.revision,0),'archived',coalesce(m.archived,false)) from pro_invoice_drafts d left join pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id where d.user_id=p_user and d.id=p_id;
$$;
create or replace function public.pro_invoice_management_page(p_user uuid,p_search text default '',p_archived boolean default false,p_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with context as (
 select d.*,c.name as client_name,w.service as work_title,coalesce(l.title,q.title) as quote_title,coalesce(m.revision,0) as management_revision,coalesce(m.archived,false) as archived
 from pro_invoice_drafts d join pro_clients c on c.user_id=d.user_id and c.id=d.client_id
 left join pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
 left join pro_work w on w.user_id=d.user_id and w.id=d.work_id
 left join pro_legacy_quotes l on l.user_id=d.user_id and l.id=coalesce(w."quoteId",case when d.source_kind='legacy_quote' then d.source_id when d.quote_origin_key like 'legacy_quote:%' then substr(d.quote_origin_key,14) end)
 left join quotes q on q.id::text=coalesce(w."externalQuoteId",case when d.source_kind='quote' then d.source_id when d.quote_origin_key like 'quote:%' then substr(d.quote_origin_key,7) end) and exists(select 1 from professionals p where p.id=q.professional_id and p.profile_id=p_user)
 where d.user_id=p_user
 ), matches as (
 select * from context where archived=p_archived and strpos(pro_catalog_search(concat_ws(' ',title,receiver_name,client_name,work_title,quote_title)),pro_catalog_search(trim(p_search)))>0
 and (p_after is null or (created_at,id)<((p_after->>'at')::timestamptz,(p_after->>'id')::uuid)) order by created_at desc,id desc limit 21
 ), page as (select * from matches order by created_at desc,id desc limit 20)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'receiver',receiver_name,'client',client_name,'clientId',client_id,'work',work_title,'quote',quote_title,'totalCents',total_cents,'revision',revision,'managementRevision',management_revision,'archived',archived,'createdAt',created_at,'updatedAt',updated_at) order by created_at desc,id desc) from page),'[]'),
 'nextCursor',case when (select count(*) from matches)>20 then (select jsonb_build_object('at',created_at,'id',id) from page order by created_at,id limit 1) else null end);
$$;
create or replace function public.pro_invoice_management_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare d pro_invoice_drafts;m pro_invoice_draft_management;c pro_invoice_draft_copies;target uuid;hash text;relation text;patch jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if p_input->>'action'='duplicate' then
  target:=(p_input->>'requestId')::uuid;hash:=md5((p_input-'requestId')::text);
  select * into c from pro_invoice_draft_copies where user_id=p_user and request_id=target;
  if c.request_id is not null then if c.input_hash<>hash then raise exception 'Copy request already used' using errcode='40001';end if;return target;end if;
  if exists(select 1 from pro_invoice_drafts where user_id=p_user and id=target) then raise exception 'Copy request collision' using errcode='40001';end if;
 end if;
 select * into d from pro_invoice_drafts where user_id=p_user and id=(p_input->>'id')::uuid for update;
 if d.id is null then raise exception 'Missing owned draft' using errcode='22023';end if;
 select * into m from pro_invoice_draft_management where user_id=p_user and draft_id=d.id;
 if d.revision is distinct from (p_input->>'revision')::integer or coalesce(m.revision,0) is distinct from (p_input->>'managementRevision')::integer then raise exception 'Draft changed before action' using errcode='40001';end if;
 if p_input->>'action' in ('archive','restore') then
  insert into pro_invoice_draft_management(user_id,draft_id,archived) values(p_user,d.id,p_input->>'action'='archive') on conflict(user_id,draft_id) do update set archived=excluded.archived,revision=pro_invoice_draft_management.revision+1,updated_at=now();
  return d.id;
 elsif p_input->>'action'='duplicate' then
  patch:=jsonb_build_object('user_id',p_user,'id',target,'source_kind','direct','source_id',target::text,'work_id',null,'quote_origin_key',null,'basis','manual','agreed_cents',null,'paid_cents',null,'balance_cents',null,'material_count',0,'material_cost',0,'source_fingerprint',hash,'revision',1,'created_at',now(),'updated_at',now());
  insert into pro_invoice_drafts select (jsonb_populate_record(null::pro_invoice_drafts,to_jsonb(d)||patch)).*;
  patch:=jsonb_build_object('user_id',p_user,'draft_id',target);
  foreach relation in array array['pro_invoice_lines','pro_invoice_preparation','pro_invoice_receiver_fiscal','pro_invoice_edited_detail','pro_invoice_edited_lines','pro_invoice_line_tax','pro_invoice_line_special_tax','pro_invoice_draft_charges'] loop
   execute format('insert into %I select (jsonb_populate_record(null::%I,to_jsonb(r)||$3)).* from %I r where user_id=$1 and draft_id=$2',relation,relation,relation) using p_user,d.id,patch;
  end loop;
  insert into pro_invoice_draft_copies values(p_user,target,d.id,hash);
  return target;
 end if;
 raise exception 'Unsupported management action' using errcode='22023';
end $$;
revoke all on function pro_invoice_active_guard(),pro_invoice_management_read(uuid,uuid),pro_invoice_management_page(uuid,text,boolean,jsonb),pro_invoice_management_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_active_guard(),pro_invoice_management_read(uuid,uuid),pro_invoice_management_page(uuid,text,boolean,jsonb),pro_invoice_management_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== expenses-local.sql =====
-- LOCAL ONLY: internal supplier/expense ledger. No fiscal issuance or external payments.
begin;
create table if not exists public.pro_expense_state(user_id uuid primary key references public.profiles(id) on delete cascade,revision bigint not null default 0 check(revision>=0));
create table if not exists public.pro_expense_suppliers(user_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,name text not null check(length(trim(name)) between 1 and 160),identification text not null default '' check(length(identification)<=40),email text not null default '' check(length(email)<=254),phone text not null default '' check(length(phone)<=40),archived boolean not null default false,primary key(user_id,id));
create table if not exists public.pro_internal_expenses(user_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,supplier_id uuid not null,supplier_name text not null check(length(trim(supplier_name)) between 1 and 160),expense_date date not null,due_date date,currency text not null check(currency='CRC'),concept text not null check(length(trim(concept)) between 1 and 300),amount_cents bigint not null check(amount_cents between 1 and 10000000000),created_at timestamptz not null default now(),primary key(user_id,id),foreign key(user_id,supplier_id) references pro_expense_suppliers(user_id,id),check(due_date is null or due_date>=expense_date));
create table if not exists public.pro_expense_payments(user_id uuid not null,expense_id uuid not null,id uuid not null,kind text not null check(kind in ('payment','reverse')),payment_id uuid,amount_cents bigint not null check(amount_cents between 1 and 10000000000),paid_on date not null,method text not null check(method in ('cash','transfer','card','other')),reference text not null check(length(reference)<=160),note text not null check(length(note)<=300),created_at timestamptz not null default now(),primary key(user_id,id),foreign key(user_id,expense_id) references pro_internal_expenses(user_id,id) on delete cascade,unique(user_id,expense_id,id),foreign key(user_id,expense_id,payment_id) references pro_expense_payments(user_id,expense_id,id),check((kind='payment' and payment_id is null) or (kind='reverse' and payment_id is not null and length(trim(note))>0)));
create unique index if not exists pro_expense_one_reverse on pro_expense_payments(user_id,payment_id) where kind='reverse';
create index if not exists pro_expense_payments_expense on pro_expense_payments(user_id,expense_id,id);
create table if not exists public.pro_expense_requests(user_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result_id uuid not null,revision bigint not null,primary key(user_id,action_id));
create or replace function public.pro_expense_summary(p_user uuid,p_id uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',e.id,'supplierId',e.supplier_id,'supplierName',e.supplier_name,'date',e.expense_date,'dueDate',e.due_date,'currency',e.currency,'concept',e.concept,'amountCents',e.amount_cents,'paidCents',v.paid,'balanceCents',e.amount_cents-v.paid,'status',case when v.paid=0 then 'pending' when v.paid=e.amount_cents then 'paid' else 'partial' end)
 from pro_internal_expenses e cross join lateral(select coalesce(sum(case when kind='payment' then amount_cents else -amount_cents end),0)::bigint paid from pro_expense_payments where user_id=e.user_id and expense_id=e.id) v where e.user_id=p_user and e.id=p_id;
$$;
create or replace function public.pro_expenses_read(p_user uuid,p_query jsonb) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare rows jsonb;cursor_id uuid:=nullif(p_query->>'after','')::uuid;detail_id uuid:=nullif(p_query->>'id','')::uuid;rev bigint;result jsonb;
begin
 if length(coalesce(p_query->>'q',''))>160 or coalesce(p_query->>'kind','expenses') not in ('suppliers','expenses') then raise exception 'Invalid query' using errcode='22023';end if;
 select coalesce((select revision from pro_expense_state where user_id=p_user),0) into rev;
 if detail_id is not null and p_query->>'kind'='suppliers' then
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'identification',s.identification,'email',s.email,'phone',s.phone,'archived',s.archived)),'[]') into rows from pro_expense_suppliers s where s.user_id=p_user and s.id=detail_id;
 return jsonb_build_object('revision',rev,'items',rows,'nextCursor',null);
 end if;
 if detail_id is not null then
 select coalesce(jsonb_agg(row order by id),'[]') into rows from(select p.id,jsonb_build_object('id',p.id,'kind',p.kind,'paymentId',p.payment_id,'amountCents',p.amount_cents,'date',p.paid_on,'method',p.method,'reference',p.reference,'note',p.note,'createdAt',p.created_at,'reversed',exists(select 1 from pro_expense_payments r where r.user_id=p.user_id and r.payment_id=p.id)) row from pro_expense_payments p where p.user_id=p_user and detail_id=p.expense_id and (cursor_id is null or p.id>cursor_id) order by p.id limit 21) t;
 return jsonb_build_object('revision',rev,'items','[]'::jsonb,'nextCursor',case when jsonb_array_length(rows)>20 then rows->19->>'id' else null end,'expense',pro_expense_summary(p_user,detail_id),'payments',(select coalesce(jsonb_agg(e),'[]') from jsonb_array_elements(rows) with ordinality t(e,n) where n<=20));
 end if;
 if coalesce(p_query->>'kind','expenses')='suppliers' then
 select coalesce(jsonb_agg(row order by id),'[]') into rows from(select s.id,jsonb_build_object('id',s.id,'name',s.name,'identification',s.identification,'email',s.email,'phone',s.phone,'archived',s.archived) row from pro_expense_suppliers s where s.user_id=p_user and (cursor_id is null or s.id>cursor_id) and s.archived=(coalesce(p_query->>'archived','0')='1') and strpos(lower(concat_ws(' ',s.name,s.identification,s.email)),lower(coalesce(p_query->>'q','')))>0 order by s.id limit 21) t;
 else
 select coalesce(jsonb_agg(row order by id),'[]') into rows from(select e.id,pro_expense_summary(p_user,e.id) row from pro_internal_expenses e where e.user_id=p_user and (cursor_id is null or e.id>cursor_id) and strpos(lower(concat_ws(' ',e.concept,e.supplier_name)),lower(coalesce(p_query->>'q','')))>0 order by e.id limit 21) t;
 end if;
 result:=jsonb_build_object('revision',rev,'items',(select coalesce(jsonb_agg(e),'[]') from jsonb_array_elements(rows) with ordinality t(e,n) where n<=20),'nextCursor',case when jsonb_array_length(rows)>20 then rows->19->>'id' else null end);return result;
end $$;
create or replace function public.pro_expenses_save(p_user uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare rev bigint;act text:=p_input->>'action';aid uuid:=(p_input->>'actionId')::uuid;rid uuid;prior pro_expense_requests;exp pro_internal_expenses;supplier pro_expense_suppliers;payment pro_expense_payments;paid bigint;amount bigint;dt date;
begin
 if not exists(select 1 from profiles where id=p_user and not coalesce(is_disabled,false)) then raise exception 'Invalid owner' using errcode='22023';end if;
 insert into pro_expense_state(user_id) values(p_user) on conflict do nothing;
 select revision into rev from pro_expense_state where user_id=p_user for update;
 select * into prior from pro_expense_requests where user_id=p_user and action_id=aid;
 if found then if prior.input<>p_input then raise exception 'Request changed' using errcode='22023';end if;return jsonb_build_object('id',prior.result_id,'revision',prior.revision);end if;
 if (p_input->>'revision')::bigint is distinct from rev then raise exception 'Revision changed' using errcode='40001';end if;
 if act='supplier' then
 rid:=(p_input->>'id')::uuid;
 insert into pro_expense_suppliers(user_id,id,name,identification,email,phone,archived) values(p_user,rid,trim(p_input->>'name'),p_input->>'identification',p_input->>'email',p_input->>'phone',(p_input->>'archived')::boolean)
 on conflict(user_id,id) do update set name=excluded.name,identification=excluded.identification,email=excluded.email,phone=excluded.phone,archived=excluded.archived;
 elsif act='expense' then
 rid:=(p_input->>'id')::uuid;select * into exp from pro_internal_expenses where user_id=p_user and id=rid;
 select * into supplier from pro_expense_suppliers where user_id=p_user and id=(p_input->>'supplierId')::uuid;
 if not found or supplier.archived and (exp.id is null or exp.supplier_id<>supplier.id) then raise exception 'Invalid supplier' using errcode='22023';end if;
 amount:=(p_input->>'amountCents')::bigint;dt:=(p_input->>'date')::date;
 select coalesce(sum(case when kind='payment' then amount_cents else -amount_cents end),0) into paid from pro_expense_payments where user_id=p_user and expense_id=rid;
 if amount<paid or exists(select 1 from pro_expense_payments where user_id=p_user and expense_id=rid and paid_on<dt) then raise exception 'Expense below payments or invalid date' using errcode='22023';end if;
 insert into pro_internal_expenses(user_id,id,supplier_id,supplier_name,expense_date,due_date,currency,concept,amount_cents) values(p_user,rid,supplier.id,case when exp.supplier_id=supplier.id then exp.supplier_name else supplier.name end,dt,(p_input->>'dueDate')::date,p_input->>'currency',trim(p_input->>'concept'),amount)
 on conflict(user_id,id) do update set supplier_id=excluded.supplier_id,supplier_name=excluded.supplier_name,expense_date=excluded.expense_date,due_date=excluded.due_date,currency=excluded.currency,concept=excluded.concept,amount_cents=excluded.amount_cents;
 elsif act in ('payment','reverse') then
 select * into exp from pro_internal_expenses where user_id=p_user and id=(p_input->>'expenseId')::uuid;
 if not found then raise exception 'Invalid expense' using errcode='22023';end if;
 rid:=aid;dt:=(p_input->>'date')::date;if dt<exp.expense_date then raise exception 'Invalid payment date' using errcode='22023';end if;
 if act='payment' then
 amount:=(p_input->>'amountCents')::bigint;select coalesce(sum(case when kind='payment' then amount_cents else -amount_cents end),0) into paid from pro_expense_payments where user_id=p_user and expense_id=exp.id;
 if amount>exp.amount_cents-paid then raise exception 'Payment exceeds balance' using errcode='22023';end if;
 insert into pro_expense_payments(user_id,expense_id,id,kind,amount_cents,paid_on,method,reference,note) values(p_user,exp.id,rid,'payment',amount,dt,p_input->>'method',p_input->>'reference',p_input->>'note');
 else
 select * into payment from pro_expense_payments where user_id=p_user and expense_id=exp.id and id=(p_input->>'paymentId')::uuid and kind='payment';
 if not found or dt<payment.paid_on then raise exception 'Invalid reversal' using errcode='22023';end if;
 insert into pro_expense_payments(user_id,expense_id,id,kind,payment_id,amount_cents,paid_on,method,reference,note) values(p_user,exp.id,rid,'reverse',payment.id,payment.amount_cents,dt,payment.method,payment.reference,trim(p_input->>'note'));
 end if;
 else raise exception 'Invalid action' using errcode='22023';end if;
 update pro_expense_state set revision=revision+1 where user_id=p_user returning revision into rev;
 insert into pro_expense_requests values(p_user,aid,p_input,rid,rev);return jsonb_build_object('id',rid,'revision',rev);
end $$;
do $$ declare name text;begin foreach name in array array['pro_expense_state','pro_expense_suppliers','pro_internal_expenses','pro_expense_payments','pro_expense_requests'] loop execute format('alter table public.%I enable row level security',name);execute format('revoke all on public.%I from public,anon,authenticated',name);execute format('grant select on public.%I to authenticated',name);execute format('grant all on public.%I to service_role',name);if not exists(select 1 from pg_policies where schemaname='public' and tablename=name and policyname=name||'_owner') then execute format('create policy %I on public.%I for select to authenticated using(user_id=(select auth.uid()))',name||'_owner',name);end if;end loop;end $$;
revoke all on function pro_expense_summary(uuid,uuid),pro_expenses_read(uuid,jsonb),pro_expenses_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_expense_summary(uuid,uuid),pro_expenses_read(uuid,jsonb),pro_expenses_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== discount-presets-local.sql =====
-- LOCAL ONLY. Commercial presets copy values into existing invoice lines.
begin;
create table if not exists public.pro_discount_preset_revisions(user_id uuid primary key references public.profiles(id) on delete cascade,revision integer not null default 0 check(revision>=0));
create table if not exists public.pro_discount_presets(
 user_id uuid references public.profiles(id) on delete cascade,id uuid not null,name text not null check(name=btrim(name) and length(name) between 1 and 80),reason text not null check(reason=btrim(reason) and length(reason) between 1 and 160),method text not null check(method in ('percent','amount')),value text not null check(value~'^[0-9]{1,9}(\.[0-9]{1,5})?$' and value::numeric>0 and value::numeric<=100000000 and (method<>'percent' or value::numeric<=100)),archived boolean not null default false,position bigint generated always as identity,primary key(user_id,id)
);
create unique index if not exists pro_discount_presets_names on public.pro_discount_presets(user_id,lower(name));
create index if not exists pro_discount_presets_page on public.pro_discount_presets(user_id,archived,position);
alter table public.pro_discount_presets enable row level security;
alter table public.pro_discount_preset_revisions enable row level security;
drop policy if exists own_read on public.pro_discount_presets;
create policy own_read on public.pro_discount_presets for select to authenticated using(user_id=auth.uid());
drop policy if exists own_read on public.pro_discount_preset_revisions;
create policy own_read on public.pro_discount_preset_revisions for select to authenticated using(user_id=auth.uid());
revoke all on public.pro_discount_presets,public.pro_discount_preset_revisions from public,anon,authenticated;
grant select on public.pro_discount_presets,public.pro_discount_preset_revisions to authenticated;
grant all on public.pro_discount_presets,public.pro_discount_preset_revisions to service_role;
grant usage,select on sequence public.pro_discount_presets_position_seq to service_role;
create or replace function public.pro_mutate_discount_preset(p_user uuid,p_action text,p_id uuid,p_preset jsonb,p_revision integer) returns integer language plpgsql security invoker set search_path=public,pg_temp as $$
declare r integer;n text;why text;m text;v text;
begin
 if p_user is null or p_action is null or p_action not in ('save','archive','restore') or p_id is null or p_revision is null or p_revision<0 then raise exception 'Invalid operation' using errcode='22023';end if;
 if p_action='save' then
  if jsonb_typeof(p_preset) is distinct from 'object' or jsonb_typeof(p_preset->'name') is distinct from 'string' or jsonb_typeof(p_preset->'reason') is distinct from 'string' or jsonb_typeof(p_preset->'method') is distinct from 'string' or jsonb_typeof(p_preset->'value') is distinct from 'string' then raise exception 'Invalid preset' using errcode='22023';end if;
  n=btrim(p_preset->>'name');why=btrim(p_preset->>'reason');m=p_preset->>'method';v=replace(btrim(p_preset->>'value'),',','.');
  if n is null or length(n) not between 1 and 80 or why is null or length(why) not between 1 and 160 or m is null or m not in ('percent','amount') or v is null or v!~'^[0-9]{1,9}(\.[0-9]{1,5})?$' then raise exception 'Invalid preset' using errcode='22023';end if;
  if v::numeric<=0 or v::numeric>100000000 or (m='percent' and v::numeric>100) then raise exception 'Invalid value' using errcode='22023';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 insert into pro_discount_preset_revisions(user_id) values(p_user) on conflict do nothing;
 select revision into r from pro_discount_preset_revisions where user_id=p_user for update;
 if r<>p_revision then raise exception 'Stale preset revision' using errcode='40001';end if;
 if p_action='save' then
  insert into pro_discount_presets(user_id,id,name,reason,method,value) values(p_user,p_id,n,why,m,v) on conflict(user_id,id) do update set name=excluded.name,reason=excluded.reason,method=excluded.method,value=excluded.value;
 else
  update pro_discount_presets set archived=(p_action='archive') where user_id=p_user and id=p_id;
  if not found then raise exception 'Unknown preset' using errcode='P0002';end if;
 end if;
 update pro_discount_preset_revisions set revision=r+1 where user_id=p_user;return r+1;
end $$;
create or replace function public.pro_discount_preset_page(p_user uuid,p_archived boolean default false,p_search text default '',p_after text default '') returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare result jsonb;r integer;
begin
 if p_user is null or p_archived is null or p_search is null or length(p_search)>160 or p_after is null or p_after!~'^[0-9]{0,18}$' then raise exception 'Invalid query' using errcode='22023';end if;
 select coalesce((select revision from pro_discount_preset_revisions where user_id=p_user),0) into r;
 with page as (select * from pro_discount_presets where user_id=p_user and archived=p_archived and position>coalesce(nullif(p_after,''),'0')::bigint and strpos(pro_catalog_search(name||' '||reason),pro_catalog_search(p_search))>0 order by position limit 21),visible as (select * from page order by position limit 20)
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name,'reason',reason,'method',method,'value',value,'archived',archived) order by position) from visible),'[]'::jsonb),'nextCursor',case when count(*)>20 then (select position::text from visible order by visible.position desc limit 1) else null end,'revision',r) into result from page;return result;
end $$;
revoke all on function public.pro_mutate_discount_preset(uuid,text,uuid,jsonb,integer),public.pro_discount_preset_page(uuid,boolean,text,text) from public,anon,authenticated;
grant execute on function public.pro_mutate_discount_preset(uuid,text,uuid,jsonb,integer),public.pro_discount_preset_page(uuid,boolean,text,text) to service_role;
commit;

-- ===== invoice-recurrence-local.sql =====
-- LOCAL ONLY. Manual single-occurrence draft copies. No scheduler, issuance, messages or debt.
begin;
create table if not exists public.pro_invoice_recurrences(
 user_id uuid not null,id uuid not null,name text not null check(length(trim(name)) between 1 and 160),source_draft_id uuid not null,source_revision integer not null check(source_revision>0),frequency text not null check(frequency in ('weekly','monthly')),start_date date not null,paused boolean not null default false,revision integer not null default 1 check(revision>0),primary key(user_id,id),foreign key(user_id,source_draft_id) references pro_invoice_drafts(user_id,id) on delete cascade
);
create table if not exists public.pro_invoice_recurrence_occurrences(
 user_id uuid not null,template_id uuid not null,occurrence_date date not null,draft_id uuid not null,source_revision integer not null,created_at timestamptz not null default now(),primary key(user_id,template_id,occurrence_date),unique(user_id,draft_id),foreign key(user_id,template_id) references pro_invoice_recurrences(user_id,id) on delete cascade,foreign key(user_id,draft_id) references pro_invoice_drafts(user_id,id) on delete cascade
);
create table if not exists public.pro_invoice_recurrence_requests(
 user_id uuid not null references profiles(id) on delete cascade,request_id uuid not null,input jsonb not null,result_id uuid not null,revision integer not null,primary key(user_id,request_id)
);
create or replace function public.pro_invoice_recurrence_day(p_start date,p_frequency text,p_index integer) returns date language plpgsql immutable strict set search_path=public,pg_temp as $$
declare first_day date;last_day date;
begin
 if p_index<0 or p_frequency not in ('weekly','monthly') then raise exception 'Invalid recurrence' using errcode='22023';end if;
 if p_frequency='weekly' then return p_start+p_index*7;end if;
 first_day:=(date_trunc('month',p_start)::date+make_interval(months=>p_index))::date;last_day:=(first_day+interval '1 month -1 day')::date;
 return first_day+least(extract(day from p_start)::integer,extract(day from last_day)::integer)-1;
end $$;
create or replace function public.pro_invoice_recurrence_row(p_user uuid,p_id uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',r.id,'name',r.name,'sourceDraftId',r.source_draft_id,'sourceRevision',r.source_revision,'frequency',r.frequency,'startDate',r.start_date,'paused',r.paused,'revision',r.revision,'sourceTitle',d.title,'currentSourceRevision',d.revision,'sourceArchived',coalesce(m.archived,false)) from pro_invoice_recurrences r join pro_invoice_drafts d on d.user_id=r.user_id and d.id=r.source_draft_id left join pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id where r.user_id=p_user and r.id=p_id;
$$;
create or replace function public.pro_invoice_recurrence_read(p_user uuid,p_query jsonb) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare rows jsonb;tid uuid:=nullif(p_query->>'id','')::uuid;after_id uuid:=nullif(p_query->>'after','')::uuid;today date:=(now() at time zone 'America/Costa_Rica')::date;horizon date;
begin
 if length(coalesce(p_query->>'q',''))>160 then raise exception 'Invalid search' using errcode='22023';end if;horizon:=(today+interval '12 months')::date;
 if tid is not null then
 select coalesce(jsonb_agg(jsonb_build_object('date',occurrence_date,'draftId',draft_id) order by occurrence_date),'[]') into rows from (select * from pro_invoice_recurrence_occurrences where user_id=p_user and template_id=tid and occurrence_date>=today and occurrence_date<=horizon order by occurrence_date limit 20) occurrences;
 return jsonb_build_object('items','[]'::jsonb,'template',pro_invoice_recurrence_row(p_user,tid),'occurrences',rows,'nextCursor',null,'today',today,'horizon',horizon);
 end if;
 select coalesce(jsonb_agg(row order by id),'[]') into rows from(select r.id,pro_invoice_recurrence_row(p_user,r.id) row from pro_invoice_recurrences r where r.user_id=p_user and (after_id is null or r.id>after_id) and strpos(lower(r.name),lower(coalesce(p_query->>'q','')))>0 order by r.id limit 21) p;
 return jsonb_build_object('items',(select coalesce(jsonb_agg(e),'[]') from jsonb_array_elements(rows) with ordinality p(e,n) where n<=20),'nextCursor',case when jsonb_array_length(rows)>20 then rows->19->>'id' else null end,'today',today,'horizon',horizon);
end $$;
create or replace function public.pro_invoice_recurrence_save(p_user uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare prior pro_invoice_recurrence_requests;r pro_invoice_recurrences;d pro_invoice_drafts;m pro_invoice_draft_management;rid uuid;v_request uuid:=(p_input->>'requestId')::uuid;act text:=p_input->>'action';day date;idx integer;rev integer;existing uuid;today date:=(now() at time zone 'America/Costa_Rica')::date;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select * into prior from pro_invoice_recurrence_requests where user_id=p_user and pro_invoice_recurrence_requests.request_id=v_request;
 if found then if prior.input<>p_input then raise exception 'Request changed' using errcode='40001';end if;return jsonb_build_object('id',prior.result_id,'revision',prior.revision);end if;
 if act='template' then
 rid:=(p_input->>'id')::uuid;select * into r from pro_invoice_recurrences where user_id=p_user and id=rid for update;
 if (p_input->>'revision')::integer is distinct from coalesce(r.revision,0) then raise exception 'Template changed' using errcode='40001';end if;
 if r.id is null or r.source_draft_id is distinct from (p_input->>'sourceDraftId')::uuid or r.source_revision is distinct from (p_input->>'sourceRevision')::integer then
 select * into d from pro_invoice_drafts where user_id=p_user and id=(p_input->>'sourceDraftId')::uuid for update;
 if d.id is null or d.revision is distinct from (p_input->>'sourceRevision')::integer or exists(select 1 from pro_invoice_draft_management where user_id=p_user and draft_id=d.id and archived) then raise exception 'Choose active current source explicitly' using errcode='22023';end if;
 end if;
 insert into pro_invoice_recurrences(user_id,id,name,source_draft_id,source_revision,frequency,start_date,paused) values(p_user,rid,trim(p_input->>'name'),(p_input->>'sourceDraftId')::uuid,(p_input->>'sourceRevision')::integer,p_input->>'frequency',(p_input->>'startDate')::date,(p_input->>'paused')::boolean) on conflict(user_id,id) do update set name=excluded.name,source_draft_id=excluded.source_draft_id,source_revision=excluded.source_revision,frequency=excluded.frequency,start_date=excluded.start_date,paused=excluded.paused,revision=pro_invoice_recurrences.revision+1 returning revision into rev;
 elsif act='generate' then
 select * into r from pro_invoice_recurrences where user_id=p_user and id=(p_input->>'templateId')::uuid for update;
 if r.id is null then raise exception 'Missing owned template' using errcode='22023';end if;
 day:=(p_input->>'date')::date;
 select draft_id into existing from pro_invoice_recurrence_occurrences where user_id=p_user and template_id=r.id and occurrence_date=day;
 if existing is not null then rid:=existing;rev:=r.revision;
 else
 if r.revision is distinct from (p_input->>'revision')::integer then raise exception 'Template changed' using errcode='40001';end if;
 if r.paused or day<r.start_date or day>(today+interval '12 months')::date then raise exception 'Paused or date outside recurrence horizon' using errcode='22023';end if;
 idx:=case when r.frequency='weekly' then (day-r.start_date)/7 else (extract(year from day)::integer-extract(year from r.start_date)::integer)*12+extract(month from day)::integer-extract(month from r.start_date)::integer end;
 if pro_invoice_recurrence_day(r.start_date,r.frequency,idx)<>day then raise exception 'Date does not match calendar' using errcode='22023';end if;
 select * into d from pro_invoice_drafts where user_id=p_user and id=r.source_draft_id for update;select * into m from pro_invoice_draft_management where user_id=p_user and draft_id=d.id;
 if d.id is null or d.revision<>r.source_revision or coalesce(m.archived,false) then raise exception 'Source changed or archived; update template explicitly' using errcode='40001';end if;
 rid:=pro_invoice_management_save(p_user,jsonb_build_object('action','duplicate','id',d.id,'revision',d.revision,'managementRevision',coalesce(m.revision,0),'requestId',v_request));
 -- Only the independent copy's planned date changes. Financial/fiscal snapshots remain exact.
 if exists(select 1 from pro_invoice_preparation where user_id=p_user and draft_id=rid) then update pro_invoice_preparation set planned_date=day where user_id=p_user and draft_id=rid;
 else insert into pro_invoice_preparation(user_id,draft_id,issuer_name,issuer_id_type,issuer_id,issuer_email,issuer_phone,issuer_address,issuer_activity,planned_date,sale_condition,credit_days,payment_method,order_reference) values(p_user,rid,'','','','','','','',day,'',0,'','');end if;
 update pro_invoice_drafts set revision=revision+1,updated_at=now() where user_id=p_user and id=rid;
 insert into pro_invoice_recurrence_occurrences(user_id,template_id,occurrence_date,draft_id,source_revision) values(p_user,r.id,day,rid,r.source_revision);rev:=r.revision;
 end if;
 else raise exception 'Invalid action' using errcode='22023';end if;
 insert into pro_invoice_recurrence_requests values(p_user,v_request,p_input,rid,rev);return jsonb_build_object('id',rid,'revision',rev);
end $$;
do $$declare name text;begin foreach name in array array['pro_invoice_recurrences','pro_invoice_recurrence_occurrences','pro_invoice_recurrence_requests'] loop execute format('alter table %I enable row level security',name);execute format('revoke all on %I from public,anon,authenticated',name);execute format('grant select on %I to authenticated',name);execute format('grant all on %I to service_role',name);if not exists(select 1 from pg_policies where schemaname='public' and tablename=name and policyname=name||'_owner') then execute format('create policy %I on %I for select to authenticated using(user_id=(select auth.uid()))',name||'_owner',name);end if;end loop;end $$;
revoke all on function pro_invoice_recurrence_day(date,text,integer),pro_invoice_recurrence_row(uuid,uuid),pro_invoice_recurrence_read(uuid,jsonb),pro_invoice_recurrence_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_recurrence_day(date,text,integer),pro_invoice_recurrence_row(uuid,uuid),pro_invoice_recurrence_read(uuid,jsonb),pro_invoice_recurrence_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== payment-receipts-local.sql =====
-- LOCAL ONLY. Private internal acknowledgement of an EXISTING recorded payment.
-- No payment/debt/ledger creation, numbering, fiscal receipt, issuance or delivery.
-- Install after client-operations, invoice-issuer and client-fiscal SQL.
begin;
create table if not exists public.pro_payment_receipts(
 user_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,
 entry_id uuid not null,
 client_id text not null,
 work_id text not null,
 client_name text not null,
 work_title text not null,
 receiver jsonb not null check(jsonb_typeof(receiver)='object'),
 issuer jsonb not null check(jsonb_typeof(issuer)='object'),
 amount_cents bigint not null check(amount_cents between 1 and 10000000000),
 payment_registered_at timestamptz not null,
 prepared_at timestamptz not null default now(),
 note text not null,
 primary key(user_id,id),unique(user_id,entry_id),
 foreign key(user_id,entry_id) references public.pro_client_entries(user_id,id) on delete cascade,
 check(id=entry_id)
);
create index if not exists pro_payment_receipts_page on public.pro_payment_receipts(user_id,prepared_at desc,id asc);
create index if not exists pro_payment_receipts_client_page on public.pro_payment_receipts(user_id,client_id,prepared_at desc,id asc);
create or replace function public.pro_payment_receipt_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 raise exception 'Prepared payment receipt snapshots are immutable' using errcode='22023';
end $$;
drop trigger if exists pro_payment_receipt_immutable on public.pro_payment_receipts;
create trigger pro_payment_receipt_immutable before update on public.pro_payment_receipts for each row execute function pro_payment_receipt_immutable();
alter table public.pro_payment_receipts enable row level security;
drop policy if exists pro_payment_receipts_owner on public.pro_payment_receipts;
create policy pro_payment_receipts_owner on public.pro_payment_receipts for select to authenticated using(user_id=(select auth.uid()));
revoke all on public.pro_payment_receipts from public,anon,authenticated;
grant select on public.pro_payment_receipts to authenticated;
grant all on public.pro_payment_receipts to service_role;
create or replace function public.pro_payment_receipt_read(p_user uuid,p_id uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',r.id,'entryId',r.entry_id,'clientId',r.client_id,'workId',r.work_id,'clientName',r.client_name,'workTitle',r.work_title,'receiver',r.receiver,'issuer',r.issuer,'amountCents',r.amount_cents,'currency','CRC','paymentRegisteredAt',r.payment_registered_at,'preparedAt',r.prepared_at,'note',r.note,'reversed',v.id is not null,'voidedAt',v.created_at,'voidReason',v.label)
 from pro_payment_receipts r
 left join pro_client_entries v on v.user_id=r.user_id and v.reversal_id=r.entry_id and v.kind='payment_void'
 where r.user_id=p_user and r.id=p_id;
$$;
create or replace function public.pro_payment_receipt_prepare(p_user uuid,p_entry uuid) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare existing jsonb;e pro_client_entries;c pro_clients;w pro_work;receiver_snapshot jsonb;issuer_snapshot jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 existing:=pro_payment_receipt_read(p_user,p_entry);
 if existing is not null then return existing;end if;
 select * into e from pro_client_entries where user_id=p_user and id=p_entry and kind='payment' for share;
 if e.id is null then return null;end if;
 select * into c from pro_clients where user_id=p_user and id=e.client_id;
 select * into w from pro_work where user_id=p_user and id=e.work_id;
 if c.id is null or w.id is null then return null;end if;
 receiver_snapshot:=pro_client_fiscal_read(p_user,e.client_id)->'receiver';
 issuer_snapshot:=pro_invoice_issuer_read(p_user)->'issuer';
 insert into pro_payment_receipts(user_id,id,entry_id,client_id,work_id,client_name,work_title,receiver,issuer,amount_cents,payment_registered_at,note)
 values(p_user,e.id,e.id,e.client_id,e.work_id,c.name,w.service,receiver_snapshot,issuer_snapshot,e.amount_cents,e.created_at,e.label);
 return pro_payment_receipt_read(p_user,e.id);
end $$;
create or replace function public.pro_payment_receipts_page(p_user uuid,p_query text default '',p_status text default 'all',p_client text default '',p_after jsonb default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if p_query is null or length(p_query)>160 or p_status is null or p_status not in ('all','active','reversed') or p_client is null or length(p_client)>160 then raise exception 'Invalid receipt query' using errcode='22023';end if;
 if p_after is not null and (jsonb_typeof(p_after)<>'object' or nullif(p_after->>'at','') is null or nullif(p_after->>'id','') is null) then raise exception 'Invalid receipt cursor' using errcode='22023';end if;
 with matches as (
 select r.prepared_at,r.id,pro_payment_receipt_read(p_user,r.id)-'receiver'-'issuer' as document
 from pro_payment_receipts r
 where r.user_id=p_user and (p_client='' or r.client_id=p_client)
 and (p_status='all' or (p_status='reversed')=exists(select 1 from pro_client_entries v where v.user_id=r.user_id and v.reversal_id=r.entry_id and v.kind='payment_void'))
 -- strpos gives literal matching: %, _ and backslash never become SQL wildcards.
 and strpos(pro_catalog_search(concat_ws(' ',r.client_name,r.work_title,r.receiver->>'name',r.receiver->>'identification',r.issuer->>'issuerName',r.note)),pro_catalog_search(p_query))>0
 and (p_after is null or r.prepared_at<(p_after->>'at')::timestamptz or r.prepared_at=(p_after->>'at')::timestamptz and r.id>(p_after->>'id')::uuid)
 order by r.prepared_at desc,r.id asc limit 21
 ), page as (select * from matches order by prepared_at desc,id asc limit 20)
 select jsonb_build_object('items',coalesce((select jsonb_agg(document order by prepared_at desc,id asc) from page),'[]'::jsonb),'nextCursor',case when (select count(*) from matches)>20 then (select jsonb_build_object('at',prepared_at,'id',id) from page order by prepared_at asc,id desc limit 1) else null end) into result;
 return result;
end $$;
revoke all on function pro_payment_receipt_immutable(),pro_payment_receipt_read(uuid,uuid),pro_payment_receipt_prepare(uuid,uuid),pro_payment_receipts_page(uuid,text,text,text,jsonb) from public,anon,authenticated;
grant execute on function pro_payment_receipt_immutable(),pro_payment_receipt_read(uuid,uuid),pro_payment_receipt_prepare(uuid,uuid),pro_payment_receipts_page(uuid,text,text,text,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== invoice-payments-local.sql =====
-- LOCAL ONLY. Internal allocation of money already received; never fiscal issuance or a charge.
-- Install after the invoice stack, client operations, and invoice management.
begin;
create table if not exists public.pro_invoice_payments(
 user_id uuid not null references profiles(id) on delete cascade,id uuid not null,
 client_id text not null,work_id text,entry_id uuid,
 amount_cents bigint not null check(amount_cents between 1 and 10000000000),
 received_on date not null,method text not null check(method in ('cash','card','transfer','sinpe','other')),
 reference text not null check(length(reference)<=160),created_at timestamptz not null default now(),
 primary key(user_id,id),unique(user_id,entry_id),
 foreign key(user_id,client_id) references pro_clients(user_id,id) on delete cascade,
 foreign key(user_id,work_id) references pro_work(user_id,id) on delete cascade,
 foreign key(user_id,entry_id) references pro_client_entries(user_id,id) on delete cascade,
 check((work_id is null)=(entry_id is null))
);
create table if not exists public.pro_invoice_payment_applications(
 user_id uuid not null references profiles(id) on delete cascade,id uuid not null,draft_id uuid not null,payment_id uuid not null,
 amount_cents bigint not null check(amount_cents between 1 and 10000000000),created_at timestamptz not null default now(),
 primary key(user_id,id),foreign key(user_id,draft_id) references pro_invoice_drafts(user_id,id) on delete cascade,
 foreign key(user_id,payment_id) references pro_invoice_payments(user_id,id) on delete cascade
);
create table if not exists public.pro_invoice_payment_voids(
 user_id uuid not null references profiles(id) on delete cascade,id uuid not null,application_id uuid not null,
 reason text not null check(length(trim(reason)) between 1 and 160),created_at timestamptz not null default now(),
 primary key(user_id,id),unique(user_id,application_id),foreign key(user_id,application_id) references pro_invoice_payment_applications(user_id,id) on delete cascade
);
create table if not exists public.pro_invoice_payment_state(
 user_id uuid not null,draft_id uuid not null,revision integer not null default 0 check(revision>=0),
 primary key(user_id,draft_id),foreign key(user_id,draft_id) references pro_invoice_drafts(user_id,id) on delete cascade
);
create table if not exists public.pro_invoice_payment_requests(
 user_id uuid not null,request_id uuid not null,input jsonb not null,draft_id uuid not null,revision integer not null,
 primary key(user_id,request_id),foreign key(user_id,draft_id) references pro_invoice_drafts(user_id,id) on delete cascade
);
create index if not exists pro_invoice_payments_scope on pro_invoice_payments(user_id,client_id,work_id,created_at desc,id desc);
create index if not exists pro_invoice_payment_applications_draft on pro_invoice_payment_applications(user_id,draft_id,created_at desc,id desc);
create index if not exists pro_invoice_payment_applications_payment on pro_invoice_payment_applications(user_id,payment_id);
create or replace function public.pro_invoice_payment_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Payment snapshots and allocation events are immutable' using errcode='22023';end $$;
do $$declare name text;begin foreach name in array array['pro_invoice_payments','pro_invoice_payment_applications','pro_invoice_payment_voids','pro_invoice_payment_state','pro_invoice_payment_requests'] loop
 execute format('alter table %I enable row level security',name);execute format('revoke all on %I from public,anon,authenticated',name);execute format('grant select on %I to authenticated',name);execute format('grant all on %I to service_role',name);
 if not exists(select 1 from pg_policies where schemaname='public' and tablename=name and policyname=name||'_owner') then execute format('create policy %I on %I for select to authenticated using(user_id=(select auth.uid()))',name||'_owner',name);end if;
 if name in ('pro_invoice_payments','pro_invoice_payment_applications','pro_invoice_payment_voids','pro_invoice_payment_requests') then execute format('drop trigger if exists pro_invoice_payment_immutable on %I',name);execute format('create trigger pro_invoice_payment_immutable before update on %I for each row execute function pro_invoice_payment_immutable()',name);end if;
end loop;end $$;
create or replace function public.pro_invoice_payment_used(p_user uuid,p_payment uuid,p_draft uuid default null) returns bigint
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(sum(a.amount_cents),0)::bigint from pro_invoice_payment_applications a join pro_invoice_payments p on p.user_id=a.user_id and p.id=a.payment_id
 where a.user_id=p_user and (p_payment is null or a.payment_id=p_payment) and (p_draft is null or a.draft_id=p_draft)
 and not exists(select 1 from pro_invoice_payment_voids v where v.user_id=a.user_id and v.application_id=a.id)
 and not exists(select 1 from pro_client_entries e where e.user_id=p.user_id and e.reversal_id=p.entry_id and e.kind='payment_void');
$$;
-- Credit notes (credits-retainers-local.sql) are not money, but they reduce what is still owed on
-- a draft (pro_credit_draft_balance). Resolved at run time so this file still installs before or
-- without the credits module; then it is 0 and the behaviour is exactly the previous one.
create or replace function public.pro_invoice_payment_credit_notes(p_user uuid,p_draft uuid) returns bigint
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v bigint;
begin
 if to_regprocedure('public.pro_credit_note_applied(uuid,uuid)') is null then return 0;end if;
 execute 'select public.pro_credit_note_applied($1,$2)' into v using p_user,p_draft;
 return coalesce(v,0);
end $$;
-- Constraint checks reselect the FINAL header, not any temporary totals used by
-- invoice tax/extras writers. This permits a valid multi-step recalculation.
-- A base-only fallback allows older installations; correction SQL replaces it.
-- Reinstalling this consumer must never overwrite the correction-aware helper.
do $install$ begin
 if to_regprocedure('public.pro_invoice_payment_metadata(uuid,uuid)') is null then
 execute $definition$create function public.pro_invoice_payment_metadata(p_user uuid,p_id uuid) returns jsonb
 language sql stable security invoker set search_path=public,pg_temp as $body$
 select jsonb_build_object('receivedOn',p.received_on,'method',p.method,'reference',p.reference,'revision',0)
 from pro_client_entries e left join pro_invoice_payments p on p.user_id=e.user_id and p.entry_id=e.id
 where e.user_id=p_user and e.id=p_id and e.kind='payment'
 union all select jsonb_build_object('receivedOn',p.received_on,'method',p.method,'reference',p.reference,'revision',0)
 from pro_invoice_payments p where p.user_id=p_user and p.id=p_id and p.entry_id is null and p.work_id is null limit 1;
 $body$$definition$;
 end if;
end $install$;
create or replace function public.pro_invoice_payment_total_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare d pro_invoice_drafts;
begin
 select * into d from pro_invoice_drafts where user_id=new.user_id and id=new.id;
 if d.id is not null and d.total_cents<pro_invoice_payment_used(d.user_id,null,d.id) then raise exception 'Invoice total is below active applications' using errcode='22023';end if;
 return null;
end $$;
drop trigger if exists pro_invoice_payment_total_guard on pro_invoice_drafts;
create constraint trigger pro_invoice_payment_total_guard after update on pro_invoice_drafts deferrable initially deferred for each row execute function pro_invoice_payment_total_guard();
create or replace function public.pro_invoice_payments_read(p_user uuid,p_id uuid,p_after jsonb default null,p_candidates_after jsonb default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare d pro_invoice_drafts;c pro_clients;w pro_work;archived boolean;applied bigint;credit_notes bigint;rev integer;account jsonb;items jsonb;next_cursor jsonb;candidates jsonb;next_candidate jsonb;work_balance bigint;
begin
 select * into d from pro_invoice_drafts where user_id=p_user and id=p_id;if d.id is null then return null;end if;
 select * into c from pro_clients where user_id=p_user and id=d.client_id;select * into w from pro_work where user_id=p_user and id=d.work_id;
 select coalesce((select m.archived from pro_invoice_draft_management m where m.user_id=p_user and m.draft_id=d.id),false) into archived;
 applied:=pro_invoice_payment_used(p_user,null,d.id);credit_notes:=pro_invoice_payment_credit_notes(p_user,d.id);select coalesce((select revision from pro_invoice_payment_state where user_id=p_user and draft_id=d.id),0) into rev;
 if d.work_id is not null then account:=pro_work_account(p_user,d.work_id);if account->>'agreedCents' is not null then work_balance:=(account->>'balanceCents')::bigint;end if;end if;
 if p_after is not null and (nullif(p_after->>'at','') is null or nullif(p_after->>'id','') is null) or p_candidates_after is not null and (nullif(p_candidates_after->>'at','') is null or nullif(p_candidates_after->>'id','') is null) then raise exception 'Invalid cursor' using errcode='22023';end if;
 with matching as (
 select a.id,a.created_at,jsonb_build_object('id',a.id,'paymentId',p.id,'entryId',p.entry_id,'amountCents',a.amount_cents,'paymentAmountCents',p.amount_cents,'receivedOn',meta.value->'receivedOn','method',meta.value->'method','reference',meta.value->'reference','createdAt',a.created_at,'voided',v.id is not null,'voidReason',v.reason,'sourceReversed',exists(select 1 from pro_client_entries e where e.user_id=p.user_id and e.reversal_id=p.entry_id and e.kind='payment_void')) document
 from pro_invoice_payment_applications a join pro_invoice_payments p on p.user_id=a.user_id and p.id=a.payment_id left join pro_invoice_payment_voids v on v.user_id=a.user_id and v.application_id=a.id cross join lateral (select pro_invoice_payment_metadata(p_user,coalesce(p.entry_id,p.id)) value) meta
 where a.user_id=p_user and a.draft_id=d.id and (p_after is null or (a.created_at,a.id)<((p_after->>'at')::timestamptz,(p_after->>'id')::uuid)) order by a.created_at desc,a.id desc limit 21
 ), page as(select * from matching order by created_at desc,id desc limit 20)
 select coalesce((select jsonb_agg(document order by created_at desc,id desc) from page),'[]'),case when (select count(*) from matching)>20 then (select jsonb_build_object('at',created_at,'id',id) from page order by created_at asc,id asc limit 1) else null end into items,next_cursor;
 with sources as (
 select e.id,e.id entry_id,p.id payment_id,e.amount_cents,e.label,e.created_at registered_at,(pro_invoice_payment_metadata(p_user,e.id)->>'receivedOn')::date received_on,pro_invoice_payment_metadata(p_user,e.id)->>'method' method,pro_invoice_payment_metadata(p_user,e.id)->>'reference' reference
 from pro_client_entries e left join pro_invoice_payments p on p.user_id=e.user_id and p.entry_id=e.id
 where d.work_id is not null and e.user_id=p_user and e.client_id=d.client_id and e.work_id=d.work_id and e.kind='payment' and not exists(select 1 from pro_client_entries v where v.user_id=e.user_id and v.reversal_id=e.id and v.kind='payment_void')
 union all
 select p.id,null::uuid,p.id,p.amount_cents,pro_invoice_payment_metadata(p_user,p.id)->>'reference',p.created_at,(pro_invoice_payment_metadata(p_user,p.id)->>'receivedOn')::date,pro_invoice_payment_metadata(p_user,p.id)->>'method',pro_invoice_payment_metadata(p_user,p.id)->>'reference' from pro_invoice_payments p where d.work_id is null and p.user_id=p_user and p.client_id=d.client_id and p.work_id is null
 ), available as(select s.*,s.amount_cents-case when s.payment_id is null then 0 else pro_invoice_payment_used(p_user,s.payment_id,null) end available_cents from sources s),matching as(
 select * from available where available_cents>0 and (p_candidates_after is null or (registered_at,id)<((p_candidates_after->>'at')::timestamptz,(p_candidates_after->>'id')::uuid)) order by registered_at desc,id desc limit 21
 ),page as(select * from matching order by registered_at desc,id desc limit 20)
 select coalesce((select jsonb_agg(jsonb_build_object('id',id,'entryId',entry_id,'paymentId',payment_id,'amountCents',amount_cents,'availableCents',available_cents,'label',label,'registeredAt',registered_at,'receivedOn',received_on,'method',method,'reference',reference) order by registered_at desc,id desc) from page),'[]'),case when (select count(*) from matching)>20 then (select jsonb_build_object('at',registered_at,'id',id) from page order by registered_at asc,id asc limit 1) else null end into candidates,next_candidate;
 return jsonb_build_object('draft',jsonb_build_object('id',d.id,'title',d.title,'clientId',d.client_id,'clientName',c.name,'workId',d.work_id,'workTitle',w.service,'totalCents',d.total_cents,'revision',d.revision,'archived',archived),'revision',rev,'summary',jsonb_build_object('appliedCents',applied,'creditNotesCents',credit_notes,'balanceCents',d.total_cents-applied-credit_notes,'workBalanceCents',work_balance,'canRecord',not archived and not c.archived and d.total_cents>applied+credit_notes and (d.work_id is null or coalesce(not w.cancelled and work_balance>0,false))),'items',items,'nextCursor',next_cursor,'candidates',candidates,'nextCandidateCursor',next_candidate);
end $$;
create or replace function public.pro_invoice_payment_mutate(p_user uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare req uuid:=(p_input->>'requestId')::uuid;act text:=p_input->>'action';prior pro_invoice_payment_requests;d pro_invoice_drafts;c pro_clients;e pro_client_entries;p pro_invoice_payments;a pro_invoice_payment_applications;rev integer;amount numeric;received date;method_value text;reference_value text;core_rev integer;metadata jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select * into prior from pro_invoice_payment_requests where user_id=p_user and request_id=req;
 if found then if prior.input<>p_input then raise exception 'Payment request changed' using errcode='40001';end if;return jsonb_build_object('id',prior.draft_id,'revision',prior.revision);end if;
 select * into d from pro_invoice_drafts where user_id=p_user and id=(p_input->>'draftId')::uuid for update;if d.id is null then return null;end if;
 insert into pro_invoice_payment_state(user_id,draft_id) values(p_user,d.id) on conflict do nothing;
 select revision into rev from pro_invoice_payment_state where user_id=p_user and draft_id=d.id for update;
 if jsonb_typeof(p_input->'draftRevision') is distinct from 'number' or jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'draftRevision')::numeric<1 or (p_input->>'draftRevision')::numeric<>round((p_input->>'draftRevision')::numeric,0) or (p_input->>'revision')::numeric<0 or (p_input->>'revision')::numeric<>round((p_input->>'revision')::numeric,0) then raise exception 'Invalid revision' using errcode='22023';end if;
 if (p_input->>'draftRevision')::numeric is distinct from d.revision::numeric or (p_input->>'revision')::numeric is distinct from rev::numeric then raise exception 'Invoice payment state changed' using errcode='40001';end if;
 if act='apply' then
 select * into c from pro_clients where user_id=p_user and id=d.client_id;
 if c.id is null or c.archived or exists(select 1 from pro_invoice_draft_management where user_id=p_user and draft_id=d.id and archived) then raise exception 'Restore active invoice/customer before applying' using errcode='22023';end if;
 amount:=(p_input->>'amountCents')::numeric;
 if jsonb_typeof(p_input->'amountCents') is distinct from 'number' or amount is null or amount<>round(amount,0) or amount<1 or amount>10000000000 or amount>d.total_cents-pro_invoice_payment_used(p_user,null,d.id) then raise exception 'Invalid application amount or invoice balance' using errcode='22023',hint='pro_invoice_balance';end if;
 -- Same balance the credits module enforces: total − payments − applied credit notes.
 if amount>d.total_cents-pro_invoice_payment_used(p_user,null,d.id)-pro_invoice_payment_credit_notes(p_user,d.id) then raise exception 'Amount exceeds the balance left after credit notes' using errcode='22023',hint='pro_credit_notes_balance';end if;
 if p_input->>'source'='new' then
 if p_input ? 'candidateId' then raise exception 'New payment has no candidate' using errcode='22023';end if;
 elsif p_input->>'source'='existing' then
 if d.work_id is not null then
 select * into e from pro_client_entries where user_id=p_user and id=(p_input->>'candidateId')::uuid and kind='payment' and client_id=d.client_id and work_id=d.work_id;
 if e.id is null or exists(select 1 from pro_client_entries where user_id=p_user and reversal_id=e.id and kind='payment_void') then raise exception 'Invalid owned work payment' using errcode='22023';end if;
 select * into p from pro_invoice_payments where user_id=p_user and entry_id=e.id;
 else
 select * into p from pro_invoice_payments where user_id=p_user and id=(p_input->>'candidateId')::uuid and client_id=d.client_id and work_id is null and entry_id is null;
 if p.id is null then raise exception 'Invalid standalone payment' using errcode='22023';end if;
 end if;
 else raise exception 'Invalid payment source' using errcode='22023';end if;
 -- Base snapshots stay immutable; reuse checks the latest audited metadata.
 metadata:=pro_invoice_payment_metadata(p_user,coalesce(e.id,p.id));
 if p.id is not null or coalesce((metadata->>'revision')::integer,0)>0 then
 received:=(metadata->>'receivedOn')::date;method_value:=metadata->>'method';reference_value:=metadata->>'reference';
 if p_input ? 'receivedOn' and p_input->>'receivedOn' is distinct from received::text or p_input ? 'method' and p_input->>'method' is distinct from method_value or p_input ? 'reference' and p_input->>'reference' is distinct from reference_value then raise exception 'Payment metadata cannot change' using errcode='22023';end if;
 else
 if jsonb_typeof(p_input->'receivedOn') is distinct from 'string' or p_input->>'receivedOn' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid received date' using errcode='22023';end if;
 received:=(p_input->>'receivedOn')::date;
 if received<date '1900-01-01' or to_char(received,'YYYY-MM-DD')<>p_input->>'receivedOn' or received>(now() at time zone 'America/Costa_Rica')::date then raise exception 'Invalid or future received date' using errcode='22023';end if;
 method_value:=p_input->>'method';reference_value:=p_input->>'reference';
 if jsonb_typeof(p_input->'method') is distinct from 'string' or method_value not in ('cash','card','transfer','sinpe','other') or jsonb_typeof(p_input->'reference') is distinct from 'string' or length(reference_value)>160 then raise exception 'Invalid payment method/reference' using errcode='22023';end if;
 end if;
 if p.id is null then
 if p_input->>'source'='new' and d.work_id is not null then
 select revision into core_rev from pro_workspace_core where user_id=p_user for update;
 perform pro_record_client_operation(p_user,jsonb_build_object('actionId',req,'clientId',d.client_id,'workId',d.work_id,'kind','payment','amountCents',amount,'note',reference_value),core_rev);
 select * into e from pro_client_entries where user_id=p_user and id=req;
 end if;
 insert into pro_invoice_payments(user_id,id,client_id,work_id,entry_id,amount_cents,received_on,method,reference) values(p_user,coalesce(e.id,req),d.client_id,d.work_id,e.id,coalesce(e.amount_cents,amount::bigint),received,method_value,reference_value) returning * into p;
 end if;
 if amount>p.amount_cents-pro_invoice_payment_used(p_user,p.id,null) then raise exception 'Payment is already allocated' using errcode='22023';end if;
 insert into pro_invoice_payment_applications(user_id,id,draft_id,payment_id,amount_cents) values(p_user,req,d.id,p.id,amount::bigint);
 elsif act='unapply' then
 select * into a from pro_invoice_payment_applications where user_id=p_user and id=(p_input->>'id')::uuid and draft_id=d.id;
 if a.id is null or exists(select 1 from pro_invoice_payment_voids where user_id=p_user and application_id=a.id) or jsonb_typeof(p_input->'reason') is distinct from 'string' or length(trim(p_input->>'reason')) not between 1 and 160 then raise exception 'Invalid application reversal' using errcode='22023';end if;
 insert into pro_invoice_payment_voids(user_id,id,application_id,reason) values(p_user,req,a.id,trim(p_input->>'reason'));
 else raise exception 'Invalid payment action' using errcode='22023';end if;
 update pro_invoice_payment_state set revision=revision+1 where user_id=p_user and draft_id=d.id returning revision into rev;
 insert into pro_invoice_payment_requests values(p_user,req,p_input,d.id,rev);
 return jsonb_build_object('id',d.id,'revision',rev);
exception when invalid_text_representation or numeric_value_out_of_range or not_null_violation or check_violation or foreign_key_violation or unique_violation or datetime_field_overflow or invalid_datetime_format then raise exception 'Invalid internal payment data' using errcode='22023';
end $$;
revoke all on function pro_invoice_payment_immutable(),pro_invoice_payment_used(uuid,uuid,uuid),pro_invoice_payment_credit_notes(uuid,uuid),pro_invoice_payment_metadata(uuid,uuid),pro_invoice_payment_total_guard(),pro_invoice_payments_read(uuid,uuid,jsonb,jsonb),pro_invoice_payment_mutate(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_payment_immutable(),pro_invoice_payment_used(uuid,uuid,uuid),pro_invoice_payment_credit_notes(uuid,uuid),pro_invoice_payment_metadata(uuid,uuid),pro_invoice_payment_total_guard(),pro_invoice_payments_read(uuid,uuid,jsonb,jsonb),pro_invoice_payment_mutate(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== payment-overview-local.sql =====
-- LOCAL ONLY. Read-only received-money overview. No new payment, debt, table or ledger mutation.
begin;
create or replace function public.pro_payment_overview_validate_cursor(p_after jsonb) returns void
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
begin
 if p_after is null then return;end if;
 if jsonb_typeof(p_after)<>'object' or jsonb_typeof(p_after->'at') is distinct from 'string' or jsonb_typeof(p_after->'id') is distinct from 'string'
 or length(p_after->>'at')>40 or (p_after->>'at') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'Invalid payment cursor' using errcode='22023';end if;
 perform (p_after->>'id')::uuid;
 if not isfinite((p_after->>'at')::timestamptz) then raise exception 'Invalid payment cursor' using errcode='22023';end if;
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then raise exception 'Invalid payment cursor' using errcode='22023';
end $$;
-- The helper is bounded to a single owned canonical id, never an unpaged list.
create or replace function public.pro_payment_overview_row(p_user uuid,p_id uuid,p_client text default '') returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with source as(
 select e.id,e.id entry_id,p.id payment_id,e.client_id,e.work_id,c.name client_name,w.service work_title,e.amount_cents,(pro_invoice_payment_metadata(p_user,e.id)->>'receivedOn')::date received_on,pro_invoice_payment_metadata(p_user,e.id)->>'method' method,pro_invoice_payment_metadata(p_user,e.id)->>'reference' reference,e.label,e.created_at registered_at,
 exists(select 1 from pro_client_entries v where v.user_id=e.user_id and v.reversal_id=e.id and v.kind='payment_void') reversed
 from pro_client_entries e join pro_clients c on c.user_id=e.user_id and c.id=e.client_id join pro_work w on w.user_id=e.user_id and w.id=e.work_id left join pro_invoice_payments p on p.user_id=e.user_id and p.entry_id=e.id
 where e.user_id=p_user and e.id=p_id and e.kind='payment' and (p_client='' or e.client_id=p_client)
 union all
 select p.id,null::uuid,p.id,p.client_id,null::text,c.name,null::text,p.amount_cents,(pro_invoice_payment_metadata(p_user,p.id)->>'receivedOn')::date,pro_invoice_payment_metadata(p_user,p.id)->>'method',pro_invoice_payment_metadata(p_user,p.id)->>'reference',pro_invoice_payment_metadata(p_user,p.id)->>'reference',p.created_at,false
 from pro_invoice_payments p join pro_clients c on c.user_id=p.user_id and c.id=p.client_id where p.user_id=p_user and p.id=p_id and p.work_id is null and p.entry_id is null and (p_client='' or p.client_id=p_client)
 ), amount as(select s.*,case when s.payment_id is null then 0 else pro_invoice_payment_used(p_user,s.payment_id,null) end applied_cents from source s)
 select jsonb_build_object('id',id,'entryId',entry_id,'paymentId',payment_id,'clientId',client_id,'clientName',client_name,'workId',work_id,'workTitle',work_title,'amountCents',amount_cents,'appliedCents',applied_cents,'availableCents',case when reversed then 0 else amount_cents-applied_cents end,'receivedOn',received_on,'method',method,'reference',reference,'label',label,'registeredAt',registered_at,'reversed',reversed) from amount limit 1;
$$;
-- Replace the earlier five-argument local reader so date filtering stays in the database.
drop function if exists public.pro_payment_overview_page(uuid,text,text,text,jsonb);
create or replace function public.pro_payment_overview_page(p_user uuid,p_query text default '',p_status text default 'all',p_client text default '',p_after jsonb default null,p_from date default null,p_through date default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if p_query is null or length(p_query)>160 then raise exception 'Invalid payment query' using errcode='22023';end if;
 if p_status is null or p_status not in ('all','available','applied','reversed','undated') then raise exception 'Invalid payment status' using errcode='22023';end if;
 if p_client is null or length(p_client)>160 then raise exception 'Invalid payment client' using errcode='22023';end if;
 if p_from is not null and not isfinite(p_from) or p_through is not null and not isfinite(p_through) or p_from is not null and p_through is not null and p_from>p_through then raise exception 'Invalid payment date range' using errcode='22023';end if;
 perform pro_payment_overview_validate_cursor(p_after);
 with source as(
 select e.id,e.id entry_id,p.id payment_id,e.client_id,e.work_id,c.name client_name,w.service work_title,e.amount_cents,(pro_invoice_payment_metadata(p_user,e.id)->>'receivedOn')::date received_on,pro_invoice_payment_metadata(p_user,e.id)->>'method' method,pro_invoice_payment_metadata(p_user,e.id)->>'reference' reference,e.label,e.created_at registered_at,
 exists(select 1 from pro_client_entries v where v.user_id=e.user_id and v.reversal_id=e.id and v.kind='payment_void') reversed
 from pro_client_entries e join pro_clients c on c.user_id=e.user_id and c.id=e.client_id join pro_work w on w.user_id=e.user_id and w.id=e.work_id left join pro_invoice_payments p on p.user_id=e.user_id and p.entry_id=e.id
 where e.user_id=p_user and e.kind='payment' and (p_client='' or e.client_id=p_client)
 union all
 select p.id,null::uuid,p.id,p.client_id,null::text,c.name,null::text,p.amount_cents,(pro_invoice_payment_metadata(p_user,p.id)->>'receivedOn')::date,pro_invoice_payment_metadata(p_user,p.id)->>'method',pro_invoice_payment_metadata(p_user,p.id)->>'reference',pro_invoice_payment_metadata(p_user,p.id)->>'reference',p.created_at,false
 from pro_invoice_payments p join pro_clients c on c.user_id=p.user_id and c.id=p.client_id where p.user_id=p_user and p.work_id is null and p.entry_id is null and (p_client='' or p.client_id=p_client)
 ), allocated as(select s.*,case when s.payment_id is null then 0 else pro_invoice_payment_used(p_user,s.payment_id,null) end applied_cents from source s),amount as(select a.*,case when reversed then 0 else amount_cents-applied_cents end available_cents from allocated a),
 filtered as materialized(
 select * from amount where (p_status='all' or p_status='reversed' and reversed or p_status='available' and not reversed and available_cents>0 or p_status='applied' and not reversed and available_cents=0 or p_status='undated' and not reversed and received_on is null)
 -- Literal matching: %, _ and backslash are ordinary characters, never wildcard patterns.
 and strpos(pro_catalog_search(concat_ws(' ',client_name,work_title,label,reference)),pro_catalog_search(p_query))>0
 and (p_status='undated' or p_from is null and p_through is null or received_on is not null and (p_from is null or received_on>=p_from) and (p_through is null or received_on<=p_through))
 ),matching as(select * from filtered where p_after is null or (registered_at,id)<((p_after->>'at')::timestamptz,(p_after->>'id')::uuid) order by registered_at desc,id desc limit 21),page as(select * from matching order by registered_at desc,id desc limit 20)
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'entryId',entry_id,'paymentId',payment_id,'clientId',client_id,'clientName',client_name,'workId',work_id,'workTitle',work_title,'amountCents',amount_cents,'appliedCents',applied_cents,'availableCents',available_cents,'receivedOn',received_on,'method',method,'reference',reference,'label',label,'registeredAt',registered_at,'reversed',reversed) order by registered_at desc,id desc) from page),'[]'),
 'nextCursor',case when (select count(*) from matching)>20 then (select jsonb_build_object('at',registered_at,'id',id) from page order by registered_at asc,id asc limit 1) else null end,
 'summary',(select jsonb_build_object('receivedCents',coalesce(sum(amount_cents) filter(where not reversed),0),'appliedCents',coalesce(sum(applied_cents) filter(where not reversed),0),'availableCents',coalesce(sum(available_cents) filter(where not reversed),0),'reversedCents',coalesce(sum(amount_cents) filter(where reversed),0),'count',count(*)) from filtered)) into result;
 return result;
end $$;
create or replace function public.pro_payment_overview_read(p_user uuid,p_id uuid,p_client text default '',p_after jsonb default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare payment jsonb;result jsonb;
begin
 if p_client is null or length(p_client)>160 then raise exception 'Invalid payment client' using errcode='22023';end if;
 perform pro_payment_overview_validate_cursor(p_after);
 payment:=pro_payment_overview_row(p_user,p_id,p_client);if payment is null then return null;end if;
 with matching as(
 select a.id,a.draft_id,a.amount_cents,a.created_at,d.title,v.id is not null voided,v.reason void_reason,coalesce(m.archived,false) draft_archived
 from pro_invoice_payment_applications a join pro_invoice_drafts d on d.user_id=a.user_id and d.id=a.draft_id left join pro_invoice_payment_voids v on v.user_id=a.user_id and v.application_id=a.id left join pro_invoice_draft_management m on m.user_id=a.user_id and m.draft_id=a.draft_id
 where a.user_id=p_user and a.payment_id=(payment->>'paymentId')::uuid and (p_after is null or (a.created_at,a.id)<((p_after->>'at')::timestamptz,(p_after->>'id')::uuid)) order by a.created_at desc,a.id desc limit 21
 ),page as(select * from matching order by created_at desc,id desc limit 20)
 select jsonb_build_object('payment',payment,'applications',coalesce((select jsonb_agg(jsonb_build_object('id',id,'draftId',draft_id,'title',title,'amountCents',amount_cents,'voided',voided,'voidReason',void_reason,'draftArchived',draft_archived) order by created_at desc,id desc) from page),'[]'),'nextCursor',case when (select count(*) from matching)>20 then (select jsonb_build_object('at',created_at,'id',id) from page order by created_at asc,id asc limit 1) else null end) into result;
 return result;
end $$;
revoke all on function pro_payment_overview_validate_cursor(jsonb),pro_payment_overview_row(uuid,uuid,text),pro_payment_overview_page(uuid,text,text,text,jsonb,date,date),pro_payment_overview_read(uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function pro_payment_overview_validate_cursor(jsonb),pro_payment_overview_row(uuid,uuid,text),pro_payment_overview_page(uuid,text,text,text,jsonb,date,date),pro_payment_overview_read(uuid,uuid,text,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== payment-metadata-local.sql =====
-- LOCAL ONLY. Audited metadata corrections; never changes money or base snapshots.
begin;
create table if not exists public.pro_payment_metadata_changes(
 user_id uuid not null references profiles(id) on delete cascade,
 id uuid not null,canonical_id uuid not null,
 entry_id uuid,payment_id uuid,
 revision integer not null check(revision>0),
 previous_received_on date,previous_method text,previous_reference text,
 received_on date not null check(received_on>=date '1900-01-01'),
 method text not null check(method in('cash','card','transfer','sinpe','other')),
 reference text not null check(length(reference)<=160),reason text not null check(length(trim(reason)) between 1 and 160),
 actor_id uuid not null check(actor_id=user_id),changed_at timestamptz not null,
 input jsonb not null,
 primary key(user_id,id),unique(user_id,canonical_id,revision),
 foreign key(user_id,entry_id) references pro_client_entries(user_id,id) on delete cascade,
 foreign key(user_id,payment_id) references pro_invoice_payments(user_id,id) on delete cascade,
 check(canonical_id=coalesce(entry_id,payment_id) and coalesce(entry_id,payment_id) is not null)
);
create index if not exists pro_payment_metadata_history on pro_payment_metadata_changes(user_id,canonical_id,changed_at desc,id desc);
alter table pro_payment_metadata_changes enable row level security;
drop policy if exists pro_payment_metadata_owner on pro_payment_metadata_changes;
create policy pro_payment_metadata_owner on pro_payment_metadata_changes for select to authenticated using(user_id=auth.uid());
revoke all on pro_payment_metadata_changes from public,anon,authenticated;
grant select on pro_payment_metadata_changes to authenticated;
grant all on pro_payment_metadata_changes to service_role;
drop trigger if exists pro_payment_metadata_immutable on pro_payment_metadata_changes;
create trigger pro_payment_metadata_immutable before update on pro_payment_metadata_changes for each row execute function pro_invoice_payment_immutable();
create or replace function public.pro_invoice_payment_metadata(p_user uuid,p_id uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with source as(
 select e.id,p.received_on,p.method,p.reference from pro_client_entries e left join pro_invoice_payments p on p.user_id=e.user_id and p.entry_id=e.id where e.user_id=p_user and e.id=p_id and e.kind='payment'
 union all select p.id,p.received_on,p.method,p.reference from pro_invoice_payments p where p.user_id=p_user and p.id=p_id and p.work_id is null and p.entry_id is null
 ),latest as(select * from pro_payment_metadata_changes where user_id=p_user and canonical_id=p_id order by revision desc limit 1)
 select jsonb_build_object('receivedOn',case when c.id is null then s.received_on else c.received_on end,'method',case when c.id is null then s.method else c.method end,'reference',case when c.id is null then s.reference else c.reference end,'revision',coalesce(c.revision,0)) from source s left join latest c on true limit 1;
$$;
create or replace function public.pro_payment_metadata_read(p_user uuid,p_id uuid,p_after jsonb default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare payment jsonb;metadata jsonb;result jsonb;
begin
 perform pro_payment_overview_validate_cursor(p_after);
 payment:=pro_payment_overview_row(p_user,p_id,'');if payment is null then return null;end if;
 metadata:=pro_invoice_payment_metadata(p_user,p_id);
 with matching as(select * from pro_payment_metadata_changes where user_id=p_user and canonical_id=p_id and (p_after is null or (changed_at,id)<((p_after->>'at')::timestamptz,(p_after->>'id')::uuid)) order by changed_at desc,id desc limit 21),page as(select * from matching order by changed_at desc,id desc limit 20)
 select jsonb_build_object('payment',payment,'revision',(metadata->>'revision')::integer,'items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'revision',revision,'receivedOn',received_on,'method',method,'reference',reference,'previousReceivedOn',previous_received_on,'previousMethod',previous_method,'previousReference',previous_reference,'reason',reason,'changedAt',changed_at,'actorId',actor_id) order by changed_at desc,id desc) from page),'[]'),'nextCursor',case when (select count(*) from matching)>20 then(select jsonb_build_object('at',changed_at,'id',id) from page order by changed_at asc,id asc limit 1) else null end) into result;
 return result;
end $$;
create or replace function public.pro_payment_metadata_correct(p_user uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare req uuid;canonical uuid;prior pro_payment_metadata_changes;payment jsonb;metadata jsonb;received date;new_revision integer;stamp timestamptz;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 req:=(p_input->>'requestId')::uuid;canonical:=(p_input->>'id')::uuid;
 if req is null or canonical is null then raise exception 'Invalid correction identity' using errcode='22023';end if;
 select * into prior from pro_payment_metadata_changes where user_id=p_user and id=req;
 if found then if prior.input is distinct from p_input then raise exception 'Correction request changed' using errcode='40001';end if;return jsonb_build_object('id',prior.canonical_id,'revision',prior.revision);end if;
 payment:=pro_payment_overview_row(p_user,canonical,'');if payment is null then return null;end if;
 metadata:=pro_invoice_payment_metadata(p_user,canonical);
 if jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')::numeric<0 or (p_input->>'revision')::numeric<>round((p_input->>'revision')::numeric,0) then raise exception 'Invalid correction revision' using errcode='22023';end if;
 if (p_input->>'revision')::numeric is distinct from (metadata->>'revision')::numeric then raise exception 'Payment metadata changed' using errcode='40001';end if;
 if (payment->>'reversed')::boolean then raise exception 'Reversed payment cannot be corrected' using errcode='22023';end if;
 if jsonb_typeof(p_input->'receivedOn') is distinct from 'string' or p_input->>'receivedOn' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid received date' using errcode='22023';end if;
 received:=(p_input->>'receivedOn')::date;
 if received<date '1900-01-01' or to_char(received,'YYYY-MM-DD')<>p_input->>'receivedOn' or received>(now() at time zone 'America/Costa_Rica')::date then raise exception 'Invalid received date' using errcode='22023';end if;
 if jsonb_typeof(p_input->'method') is distinct from 'string' or p_input->>'method' not in('cash','card','transfer','sinpe','other') or jsonb_typeof(p_input->'reference') is distinct from 'string' or length(p_input->>'reference')>160 or jsonb_typeof(p_input->'reason') is distinct from 'string' or length(trim(p_input->>'reason')) not between 1 and 160 then raise exception 'Invalid correction metadata' using errcode='22023';end if;
 if metadata->>'receivedOn' is not distinct from p_input->>'receivedOn' and metadata->>'method' is not distinct from p_input->>'method' and metadata->>'reference' is not distinct from p_input->>'reference' then raise exception 'Correction must change metadata' using errcode='22023';end if;
 new_revision:=(metadata->>'revision')::integer+1;
 select greatest(clock_timestamp(),coalesce(max(changed_at)+interval '1 microsecond','-infinity'::timestamptz)) into stamp from pro_payment_metadata_changes where user_id=p_user and canonical_id=canonical;
 insert into pro_payment_metadata_changes(user_id,id,canonical_id,entry_id,payment_id,revision,previous_received_on,previous_method,previous_reference,received_on,method,reference,reason,actor_id,changed_at,input)
 values(p_user,req,canonical,(payment->>'entryId')::uuid,case when payment->>'entryId' is null then (payment->>'paymentId')::uuid else null end,new_revision,(metadata->>'receivedOn')::date,metadata->>'method',metadata->>'reference',received,p_input->>'method',p_input->>'reference',trim(p_input->>'reason'),p_user,stamp,p_input);
 return jsonb_build_object('id',canonical,'revision',new_revision);
exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow or invalid_datetime_format or check_violation or not_null_violation or foreign_key_violation then raise exception 'Invalid metadata correction' using errcode='22023';
end $$;
revoke all on function pro_invoice_payment_metadata(uuid,uuid),pro_payment_metadata_read(uuid,uuid,jsonb),pro_payment_metadata_correct(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_payment_metadata(uuid,uuid),pro_payment_metadata_read(uuid,uuid,jsonb),pro_payment_metadata_correct(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== client-statement-local.sql =====
-- LOCAL ONLY. Read-only statement derived from existing agreements and canonical payments.
-- Draft invoices are not debts. Standalone payments never offset work balances implicitly.
begin;
create or replace function public.pro_client_statement_page(p_user uuid,p_client text,p_after jsonb default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if p_client is null or length(p_client) not between 1 and 160 then raise exception 'Invalid client' using errcode='22023';end if;
 perform pro_payment_overview_validate_cursor(p_after);
 with accounts as materialized(
 select pro_work_account(p_user,w.id) a,coalesce(to_char(pro_instant(w.start) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'') at from pro_work w where w.user_id=p_user and w."clientId"=p_client
 ),
 ledger as(
 select e.id,e.kind,e.work_id,w.service work_title,w.cancelled work_cancelled,e.amount_cents,e.created_at at,e.label,e.position,
 case when e.kind='agreement' then (select prev.amount_cents from pro_client_entries prev where prev.user_id=e.user_id and prev.work_id=e.work_id and prev.kind='agreement' and prev.position<e.position order by prev.position desc limit 1) else null end previous_agreement,
 exists(select 1 from pro_client_entries v where v.user_id=e.user_id and v.reversal_id=e.id and v.kind='payment_void') reversed,
 e.kind='agreement' and exists(select 1 from pro_client_entries n where n.user_id=e.user_id and n.work_id=e.work_id and n.kind='agreement' and n.position>e.position) superseded,
 case when e.kind in ('payment','payment_void') then pro_invoice_payment_metadata(p_user,case when e.kind='payment' then e.id else e.reversal_id end) else null end metadata,
 case when e.kind='payment' then e.id when e.kind='payment_void' then e.reversal_id else null end payment_id
 from pro_client_entries e join pro_work w on w.user_id=e.user_id and w.id=e.work_id where e.user_id=p_user and e.client_id=p_client and w."clientId"=p_client and e.kind in ('agreement','payment','payment_void')
 ),standalone as materialized(
 select p.*,pro_invoice_payment_metadata(p_user,p.id) metadata,pro_invoice_payment_used(p_user,p.id,null) applied from pro_invoice_payments p where p.user_id=p_user and p.client_id=p_client and p.work_id is null and p.entry_id is null
 ),events as(
 select id,at,jsonb_build_object('id',id,'kind',kind,'workId',work_id,'workTitle',work_title,'workCancelled',work_cancelled,'amountCents',amount_cents,'previousAgreementCents',previous_agreement,'balanceDeltaCents',case when kind='agreement' then amount_cents-coalesce(previous_agreement,0) when kind='payment' then -amount_cents else amount_cents end,'at',at,'receivedOn',case when kind='payment' then metadata->'receivedOn' else null end,'method',metadata->'method','reference',metadata->'reference','label',label,'reversed',reversed,'superseded',superseded,'paymentId',payment_id) document from ledger
 union all
 select id,created_at,jsonb_build_object('id',id,'kind','direct_payment','workId',null,'workTitle',null,'workCancelled',false,'amountCents',amount_cents,'previousAgreementCents',null,'balanceDeltaCents',0,'at',created_at,'receivedOn',metadata->'receivedOn','method',metadata->'method','reference',metadata->'reference','label',coalesce(metadata->>'reference',''),'reversed',false,'superseded',false,'paymentId',id) from standalone
 ),matches as(select * from events where p_after is null or (at,id)<((p_after->>'at')::timestamptz,(p_after->>'id')::uuid) order by at desc,id desc limit 21),page as(select * from matches order by at desc,id desc limit 20)
 select jsonb_build_object('revision',md5(coalesce((select jsonb_build_object('id',id,'name',name,'archived',archived)::text from pro_clients where user_id=p_user and id=p_client),'')||coalesce((select jsonb_agg(a order by a->>'id')::text from accounts),'[]')||coalesce((select jsonb_agg(document order by at desc,id desc)::text from events),'[]')||coalesce((select jsonb_agg(jsonb_build_object('id',id,'applied',applied) order by id)::text from standalone),'[]')),'client',(select jsonb_build_object('id',id,'name',name,'archived',archived) from pro_clients where user_id=p_user and id=p_client),
 'summary',jsonb_build_object('agreedCents',coalesce((select sum((a->>'agreedCents')::bigint) from accounts),0),'paidCents',coalesce((select sum((a->>'paidCents')::bigint) from accounts),0),'balanceCents',coalesce((select sum(greatest((a->>'balanceCents')::bigint,0)) from accounts),0),'creditCents',coalesce((select sum(greatest(-(a->>'balanceCents')::bigint,0)) from accounts),0),'unpriced',(select count(*) from accounts where a->>'agreedCents' is null and not(a->>'cancelled')::boolean),'workCount',(select count(*) from accounts),'standaloneReceivedCents',coalesce((select sum(amount_cents) from standalone),0),'standaloneAvailableCents',coalesce((select sum(amount_cents-applied) from standalone),0)),
 'items',coalesce((select jsonb_agg(document order by at desc,id desc) from page),'[]'),'nextCursor',case when (select count(*) from matches)>20 then (select jsonb_build_object('at',at,'id',id) from page order by at asc,id asc limit 1) else null end) into result
 where exists(select 1 from pro_clients where user_id=p_user and id=p_client);
 return result;
end $$;
revoke all on function pro_client_statement_page(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function pro_client_statement_page(uuid,text,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== client-pending-local.sql =====
-- LOCAL PRO ONLY. Read-only projection; no records or statuses are modified.
begin;
create or replace function public.pro_client_pending_page(p_user uuid,p_client text,p_after jsonb default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare moment timestamptz:=statement_timestamp(); result jsonb;
begin
 if p_client is null or length(p_client) not between 1 and 160 then raise exception 'Invalid client' using errcode='22023'; end if;
 if p_after is not null then
  if jsonb_typeof(p_after)<>'object' or not(p_after ?& array['priority','at','key','asOf'])
    or jsonb_typeof(p_after->'priority')<>'number' or (p_after->>'priority') !~ '^[0-4]$'
    or jsonb_typeof(p_after->'at')<>'string' or length(p_after->>'at')>40
    or jsonb_typeof(p_after->'key')<>'string' or length(p_after->>'key') not between 1 and 180
    or jsonb_typeof(p_after->'asOf')<>'string' or length(p_after->>'asOf')>40 or pro_instant(p_after->>'asOf') is null
  then raise exception 'Invalid cursor' using errcode='22023'; end if;
  moment:=pro_instant(p_after->>'asOf');
 end if;
 if not exists(select 1 from pro_clients where user_id=p_user and id=p_client) then return null; end if;
 with candidates as (
  select w.id,'work:'||w.id as key,'work'::text as kind,w.service as title,
   case when pro_instant(w."end") is null or pro_instant(w."end")<=moment then 'review' else 'upcoming' end as reason,
   coalesce(to_char(pro_instant(w.start) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'') as at,false as legacy,
   case when pro_instant(w."end") is null or pro_instant(w."end")<=moment then 0 else 1 end as priority,null::integer as "sourceRevision",null::text as "requestStatus"
  from pro_work w where w.user_id=p_user and w."clientId"=p_client and not w.cancelled and w.stage<>'completed'
  union all
  select q.id::text,'standard:'||q.id::text,'quote',coalesce(q.title,''),
   case when q.status='accepted' then 'schedule' when q.status='draft' then 'prepare' when q.valid_until<(moment at time zone 'America/Costa_Rica')::date then 'expired' else 'response' end,
   to_char(q.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),false,
   case when q.status='accepted' then 2 when q.status='draft' or q.valid_until<(moment at time zone 'America/Costa_Rica')::date then 3 else 4 end,null::integer,null::text
  from pro_quote_links l join quotes q on q.id::text=l."quoteId"
   join professionals p on p.id=q.professional_id and p.profile_id=p_user
  where l.user_id=p_user and l."clientId"=p_client and q.deleted_at is null and q.status in ('draft','sent','accepted')
   and (q.status<>'accepted' or not exists(select 1 from pro_work w where w.user_id=p_user and w."externalQuoteId"=q.id::text and not w.cancelled))
  union all
  select q.id,'legacy:'||q.id,'quote',q.title,case q.status when 'accepted' then 'schedule' else 'prepare' end,'',true,case q.status when 'accepted' then 2 else 3 end,null::integer,null::text
  from pro_legacy_quotes q where q.user_id=p_user and q."clientId"=p_client and q.status in ('draft','accepted')
   and (q.status<>'accepted' or not exists(select 1 from pro_work w where w.user_id=p_user and w."quoteId"=q.id and not w.cancelled))
  union all
  select r.id::text,'request:'||r.id::text,'request',r.service,
   case when r.status='requested' then 'request' else 'confirmation' end,
   coalesce(to_char((case when r.status='proposed' then r.proposed_start else r.requested_start end) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),''),false,
   case when r.status='requested' then 0 else 4 end,r.revision,r.status
  from pro_appointment_requests r
  where r.owner_id=p_user and p_client='reservation-'||r.client_user_id::text
   and r.status in ('requested','proposed') and r.work_id is null
 ), page as (
  select * from candidates where p_after is null or (priority,at,key)>((p_after->>'priority')::integer,p_after->>'at',p_after->>'key') order by priority,at,key limit 7
 )
 select jsonb_build_object('asOf',moment,'fingerprint',(select md5(coalesce(jsonb_agg(to_jsonb(c) order by priority,at,key)::text,'[]')) from candidates c),
  'summary',(select jsonb_build_object('review',count(*) filter(where reason='review'),'upcoming',count(*) filter(where reason='upcoming'),'prepare',count(*) filter(where reason='prepare'),'response',count(*) filter(where reason='response'),'schedule',count(*) filter(where reason='schedule'),'request',count(*) filter(where reason='request'),'confirmation',count(*) filter(where reason='confirmation'),'expired',count(*) filter(where reason='expired')) from candidates),
  'items',coalesce((select jsonb_agg(to_jsonb(r) order by priority,at,key) from(select * from page order by priority,at,key limit 6) r),'[]'),
  'nextCursor',case when(select count(*) from page)>6 then(select jsonb_build_object('priority',priority,'at',at,'key',key,'asOf',moment) from page order by priority,at,key offset 5 limit 1) else null end) into result;
 return result;
end;$$;
revoke all on function public.pro_client_pending_page(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.pro_client_pending_page(uuid,text,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== service-packages-local.sql =====
-- LOCAL PRO ONLY. Commercial snapshots shared by quote and invoice editors.
-- No workspace rewrite, stock movement, payment, debt or fiscal emission.
begin;
create table if not exists public.pro_service_package_revisions(user_id uuid primary key references public.profiles(id) on delete cascade,revision integer not null default 0 check(revision>=0));
create table if not exists public.pro_service_packages(
 user_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,name text not null check(name=btrim(name) and length(name) between 1 and 80),notes text not null default '' check(notes=btrim(notes) and length(notes)<=1000),archived boolean not null default false,position bigint generated always as identity,primary key(user_id,id)
);
create unique index if not exists pro_service_packages_names on public.pro_service_packages(user_id,lower(name));
create index if not exists pro_service_packages_page on public.pro_service_packages(user_id,archived,position);
create table if not exists public.pro_service_package_lines(
 user_id uuid not null,package_id uuid not null,line_number integer not null check(line_number between 1 and 20),kind text not null check(kind in ('product','service')),description text not null check(description=btrim(description) and length(description) between 1 and 140),quantity text not null check(quantity~'^[0-9]{1,4}(\.[0-9]{1,2})?$' and quantity::numeric>0 and quantity::numeric<=9999),unit_price text not null check(unit_price~'^[0-9]{1,9}$' and unit_price::numeric<=100000000),sku text not null check(length(sku)<=160 and sku=btrim(sku)),unit text not null check(length(unit)<=30 and unit=btrim(unit)),cabys text not null check(cabys~'^([0-9]{13})?$'),primary key(user_id,package_id,line_number),foreign key(user_id,package_id) references public.pro_service_packages(user_id,id) on delete cascade
);
create table if not exists public.pro_service_package_requests(user_id uuid not null references profiles(id) on delete cascade,request_id uuid not null,input jsonb not null,result jsonb not null,primary key(user_id,request_id));
do $$declare n text;begin foreach n in array array['pro_service_packages','pro_service_package_lines','pro_service_package_revisions','pro_service_package_requests'] loop
 execute format('alter table %I enable row level security',n);
 execute format('revoke all on %I from public,anon,authenticated',n);
 execute format('grant select on %I to authenticated',n);
 execute format('grant all on %I to service_role',n);
 if not exists(select 1 from pg_policies where schemaname='public' and tablename=n and policyname=n||'_owner') then execute format('create policy %I on %I for select to authenticated using(user_id=(select auth.uid()))',n||'_owner',n);end if;
 end loop;end $$;
grant usage,select on sequence public.pro_service_packages_position_seq to service_role;
create or replace function public.pro_mutate_service_package(p_user uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare action text;pid uuid;request uuid;rev integer;current_rev integer;prior pro_service_package_requests;body jsonb;line jsonb;n text;note text;qty text;price text;total numeric:=0;result jsonb;
begin
 if p_user is null or jsonb_typeof(p_input) is distinct from 'object' or (p_input-array['action','id','revision','requestId','package'])<>'{}'::jsonb or jsonb_typeof(p_input->'action') is distinct from 'string' or (p_input->>'action') not in ('save','archive','restore') or jsonb_typeof(p_input->'id') is distinct from 'string' or jsonb_typeof(p_input->'requestId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]{1,10}$' then raise exception 'Invalid operation' using errcode='22023';end if;
 action:=p_input->>'action';pid:=(p_input->>'id')::uuid;request:=(p_input->>'requestId')::uuid;rev:=(p_input->>'revision')::integer;
 if action='save' then
  body:=p_input->'package';
  if jsonb_typeof(body) is distinct from 'object' or (body-array['name','notes','lines'])<>'{}'::jsonb or jsonb_typeof(body->'name') is distinct from 'string' or jsonb_typeof(body->'notes') is distinct from 'string' or jsonb_typeof(body->'lines') is distinct from 'array' then raise exception 'Invalid package' using errcode='22023';end if;
  n:=btrim(body->>'name');note:=btrim(body->>'notes');
  if length(n) not between 1 and 80 or length(note)>1000 or jsonb_array_length(body->'lines') not between 1 and 20 then raise exception 'Invalid package' using errcode='22023';end if;
  for line in select value from jsonb_array_elements(body->'lines') loop
   if jsonb_typeof(line) is distinct from 'object' or not(line ?& array['kind','description','quantity','unitPrice','sku','unit','cabys']) or (line-array['kind','description','quantity','unitPrice','sku','unit','cabys'])<>'{}'::jsonb or exists(select 1 from jsonb_each(line) where jsonb_typeof(value)<>'string') then raise exception 'Invalid line' using errcode='22023';end if;
   qty:=replace(btrim(line->>'quantity'),',','.');price:=btrim(line->>'unitPrice');
   if line->>'kind' not in ('product','service') or length(btrim(line->>'description')) not between 1 and 140 or length(btrim(line->>'sku'))>160 or length(btrim(line->>'unit'))>30 or (line->>'cabys')!~'^([0-9]{13})?$' or qty!~'^[0-9]{1,4}(\.[0-9]{1,2})?$' or price!~'^[0-9]{1,9}$' then raise exception 'Invalid line' using errcode='22023';end if;
   if qty::numeric<=0 or qty::numeric>9999 or price::numeric>100000000 then raise exception 'Invalid amount' using errcode='22023';end if;
   total:=total+qty::numeric*price::numeric;
  end loop;
  if total>100000000 then raise exception 'Package total exceeds limit' using errcode='22023';end if;
 elsif p_input ? 'package' then raise exception 'Unexpected package body' using errcode='22023';
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select * into prior from pro_service_package_requests where user_id=p_user and request_id=request;
 if found then
  if prior.input<>p_input then raise exception 'Request reuse with different content' using errcode='22023';end if;
  return prior.result;
 end if;
 insert into pro_service_package_revisions(user_id) values(p_user) on conflict do nothing;
 select revision into current_rev from pro_service_package_revisions where user_id=p_user for update;
 if current_rev<>rev then raise exception 'Stale package revision' using errcode='40001';end if;
 if action='save' then
  insert into pro_service_packages(user_id,id,name,notes) values(p_user,pid,n,note) on conflict(user_id,id) do update set name=excluded.name,notes=excluded.notes;
  delete from pro_service_package_lines where user_id=p_user and package_id=pid;
  insert into pro_service_package_lines(user_id,package_id,line_number,kind,description,quantity,unit_price,sku,unit,cabys)
  select p_user,pid,ordinality::integer,value->>'kind',btrim(value->>'description'),replace(btrim(value->>'quantity'),',','.'),btrim(value->>'unitPrice'),btrim(value->>'sku'),btrim(value->>'unit'),value->>'cabys' from jsonb_array_elements(body->'lines') with ordinality;
 else
  update pro_service_packages set archived=(action='archive') where user_id=p_user and id=pid;
  if not found then raise exception 'Unknown package' using errcode='P0002';end if;
 end if;
 update pro_service_package_revisions set revision=current_rev+1 where user_id=p_user;
 result:=jsonb_build_object('revision',current_rev+1,'id',pid);
 insert into pro_service_package_requests(user_id,request_id,input,result) values(p_user,request,p_input,result);
 return result;
end $$;
create or replace function public.pro_service_package_page(p_user uuid,p_archived boolean default false,p_search text default '',p_after text default '',p_id uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if p_user is null or p_archived is null or p_search is null or length(p_search)>160 or p_after is null or p_after!~'^[0-9]{0,18}$' then raise exception 'Invalid query' using errcode='22023';end if;
 with matches as(select * from pro_service_packages where user_id=p_user and archived=p_archived and (p_id is null or id=p_id) and position>coalesce(nullif(p_after,''),'0')::bigint and strpos(pro_catalog_search(name||' '||notes),pro_catalog_search(p_search))>0 order by position limit 21),page as(select * from matches order by position limit 20)
 select jsonb_build_object('revision',coalesce((select revision from pro_service_package_revisions where user_id=p_user),0),'items',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'notes',p.notes,'archived',p.archived,'lines',(select jsonb_agg(jsonb_build_object('kind',l.kind,'description',l.description,'quantity',l.quantity,'unitPrice',l.unit_price,'sku',l.sku,'unit',l.unit,'cabys',l.cabys) order by line_number) from pro_service_package_lines l where l.user_id=p.user_id and l.package_id=p.id)) order by position) from page p),'[]'::jsonb),'nextCursor',case when(select count(*) from matches)>20 then(select p.position::text from page p order by p.position desc limit 1) else null end) into result;
 return result;
end $$;
revoke all on function public.pro_mutate_service_package(uuid,jsonb),public.pro_service_package_page(uuid,boolean,text,text,uuid) from public,anon,authenticated;
grant execute on function public.pro_mutate_service_package(uuid,jsonb),public.pro_service_package_page(uuid,boolean,text,text,uuid) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== work-costs-local.sql =====
-- LOCAL PRO ONLY. Internal job costs; no invoice issuance, bank operation or workspace rewrite.
begin;
create table if not exists public.pro_work_cost_state(user_id uuid primary key references profiles(id) on delete cascade,revision bigint not null default 0 check(revision>=0));
create table if not exists public.pro_work_cost_entries(
 user_id uuid not null references profiles(id) on delete cascade,id uuid not null,work_id text not null,position bigint generated always as identity,
 kind text not null check(kind in ('time','time_void','expense','expense_unlink')),recorded_on date not null,minutes integer,hourly_cost_cents bigint,amount_cents bigint,note text not null default '' check(length(note)<=300),expense_id uuid,supplier_name text,reversal_id uuid,created_at timestamptz not null default now(),
 primary key(user_id,id),foreign key(user_id,work_id) references pro_work(user_id,id),foreign key(user_id,expense_id) references pro_internal_expenses(user_id,id),foreign key(user_id,reversal_id) references pro_work_cost_entries(user_id,id),
 check((kind in ('time','time_void') and minutes between 1 and 1440 and (hourly_cost_cents is null or hourly_cost_cents between 0 and 10000000000) and expense_id is null and supplier_name is null and amount_cents is not distinct from case when hourly_cost_cents is null then null else round(minutes::numeric*hourly_cost_cents/60)::bigint end) or (kind in ('expense','expense_unlink') and expense_id is not null and minutes is null and hourly_cost_cents is null and amount_cents between 1 and 10000000000 and supplier_name is not null)),
 check((kind in ('time','expense') and reversal_id is null) or (kind in ('time_void','expense_unlink') and reversal_id is not null and length(btrim(note))>0))
);
-- Conditional SQL checks must reject unknown NULL results explicitly.
do $$begin
 if not exists(select 1 from pg_constraint where conrelid='public.pro_work_cost_entries'::regclass and conname='pro_work_cost_required_values') then
  alter table public.pro_work_cost_entries add constraint pro_work_cost_required_values check((kind in ('time','time_void') and minutes is not null) or (kind in ('expense','expense_unlink') and amount_cents is not null));
 end if;
end $$;
create unique index if not exists pro_work_cost_one_reversal on public.pro_work_cost_entries(user_id,reversal_id) where reversal_id is not null;
create index if not exists pro_work_cost_work on public.pro_work_cost_entries(user_id,work_id,position);
create table if not exists public.pro_work_expense_assignments(user_id uuid not null references profiles(id) on delete cascade,expense_id uuid not null,work_id text not null,entry_id uuid not null,primary key(user_id,expense_id),foreign key(user_id,expense_id) references pro_internal_expenses(user_id,id),foreign key(user_id,work_id) references pro_work(user_id,id),foreign key(user_id,entry_id) references pro_work_cost_entries(user_id,id));
create table if not exists public.pro_work_cost_requests(user_id uuid not null references profiles(id) on delete cascade,request_id uuid not null,input jsonb not null,result jsonb not null,primary key(user_id,request_id));
create or replace function public.pro_work_costs_mutate(p_user uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;wid text;cid text;rid uuid;rev bigint;current_rev bigint;prior pro_work_cost_requests;w pro_work;c pro_clients;original pro_work_cost_entries;expense pro_internal_expenses;eid uuid;rate bigint;mins integer;dt date;amt bigint;note_value text;reason text;expense_result jsonb;expense_rev bigint;result jsonb;keys text[];
begin
 if p_user is null or jsonb_typeof(p_input) is distinct from 'object' or not(p_input ?& array['action','clientId','workId','requestId','revision']) or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'clientId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'requestId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]{1,15}$' then raise exception 'Invalid operation' using errcode='22023';end if;
 act:=p_input->>'action';wid:=p_input->>'workId';cid:=p_input->>'clientId';rid:=(p_input->>'requestId')::uuid;rev:=(p_input->>'revision')::bigint;
 keys:=array['action','clientId','workId','requestId','revision']||case act when 'add_time' then array['date','minutes','hourlyCostCents','note'] when 'edit_time' then array['entryId','reason','date','minutes','hourlyCostCents','note'] when 'void_time' then array['entryId','reason'] when 'link_expense' then array['expenseId','expenseRevision'] when 'unlink_expense' then array['entryId','reason'] when 'create_expense' then array['expenseId','supplierId','date','concept','amountCents','expenseRevision'] else null end;
 if act not in ('add_time','edit_time','void_time','link_expense','unlink_expense','create_expense') or keys is null or (p_input-keys)<>'{}'::jsonb or not(p_input ?& keys) or length(wid) not between 1 and 160 or length(cid) not between 1 and 160 or not exists(select 1 from profiles where id=p_user and not coalesce(is_disabled,false)) then raise exception 'Invalid operation' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('work-costs:'||p_user::text,0));
 select * into prior from pro_work_cost_requests where user_id=p_user and request_id=rid;
 if found then if prior.input<>p_input then raise exception 'Request changed' using errcode='22023';end if;return prior.result;end if;
 select * into w from pro_work where user_id=p_user and id=wid and "clientId"=cid for update;
 if not found then raise exception 'Invalid work' using errcode='P0002';end if;
 select * into c from pro_clients where user_id=p_user and id=cid;
 if act not in ('void_time','unlink_expense') and (w.cancelled or c.archived) then raise exception 'Inactive work or client' using errcode='22023';end if;
 insert into pro_work_cost_state(user_id) values(p_user) on conflict do nothing;
 select revision into current_rev from pro_work_cost_state where user_id=p_user for update;
 if current_rev<>rev then raise exception 'Costs changed' using errcode='40001';end if;
 if act in ('add_time','edit_time','create_expense') then
  if jsonb_typeof(p_input->'date') is distinct from 'string' or (p_input->>'date')!~'^\d{4}-\d{2}-\d{2}$' then raise exception 'Invalid date' using errcode='22023';end if;
  dt:=(p_input->>'date')::date;if dt<'1900-01-01'::date or dt>(now() at time zone 'America/Costa_Rica')::date then raise exception 'Invalid date' using errcode='22023';end if;
 end if;
 if act in ('add_time','edit_time') then
  if jsonb_typeof(p_input->'minutes') is distinct from 'number' or (p_input->>'minutes')!~'^[0-9]{1,4}$' or jsonb_typeof(p_input->'hourlyCostCents') not in ('number','null') or jsonb_typeof(p_input->'note') is distinct from 'string' or length(btrim(p_input->>'note'))>300 then raise exception 'Invalid time' using errcode='22023';end if;
  mins:=(p_input->>'minutes')::integer;if mins not between 1 and 1440 then raise exception 'Invalid duration' using errcode='22023';end if;
  if jsonb_typeof(p_input->'hourlyCostCents')='number' then if (p_input->>'hourlyCostCents')!~'^[0-9]{1,11}$' then raise exception 'Invalid rate' using errcode='22023';end if;rate:=(p_input->>'hourlyCostCents')::bigint;if rate>10000000000 then raise exception 'Invalid rate' using errcode='22023';end if;end if;
  note_value:=btrim(p_input->>'note');amt:=case when rate is null then null else round(mins::numeric*rate/60)::bigint end;
 end if;
 if act in ('void_time','edit_time','unlink_expense') then
  if jsonb_typeof(p_input->'entryId') is distinct from 'string' or jsonb_typeof(p_input->'reason') is distinct from 'string' or length(btrim(p_input->>'reason')) not between 1 and 300 then raise exception 'Invalid reversal' using errcode='22023';end if;
  reason:=btrim(p_input->>'reason');
  select * into original from pro_work_cost_entries where user_id=p_user and id=(p_input->>'entryId')::uuid and work_id=wid and kind=case when act='unlink_expense' then 'expense' else 'time' end for update;
  if not found or exists(select 1 from pro_work_cost_entries where user_id=p_user and reversal_id=original.id) then raise exception 'Invalid entry' using errcode='22023';end if;
  if act='unlink_expense' then
   select * into expense from pro_internal_expenses where user_id=p_user and id=original.expense_id for update;
   if not found then raise exception 'Invalid expense' using errcode='22023';end if;
  end if;
  insert into pro_work_cost_entries(user_id,id,work_id,kind,recorded_on,minutes,hourly_cost_cents,amount_cents,note,expense_id,supplier_name,reversal_id)
  values(p_user,case when act='edit_time' then gen_random_uuid() else rid end,wid,case when act='unlink_expense' then 'expense_unlink' else 'time_void' end,(now() at time zone 'America/Costa_Rica')::date,original.minutes,original.hourly_cost_cents,case when act='unlink_expense' then expense.amount_cents else original.amount_cents end,reason,original.expense_id,case when act='unlink_expense' then expense.supplier_name else original.supplier_name end,original.id);
  if act='unlink_expense' then delete from pro_work_expense_assignments where user_id=p_user and expense_id=original.expense_id and entry_id=original.id;end if;
 end if;
 if act in ('add_time','edit_time') then
  insert into pro_work_cost_entries(user_id,id,work_id,kind,recorded_on,minutes,hourly_cost_cents,amount_cents,note) values(p_user,rid,wid,'time',dt,mins,rate,amt,note_value);
 elsif act in ('link_expense','create_expense') then
  if jsonb_typeof(p_input->'expenseId') is distinct from 'string' or jsonb_typeof(p_input->'expenseRevision') is distinct from 'number' or (p_input->>'expenseRevision')!~'^[0-9]{1,15}$' then raise exception 'Invalid expense' using errcode='22023';end if;
  eid:=(p_input->>'expenseId')::uuid;
  insert into pro_expense_state(user_id) values(p_user) on conflict do nothing;
  select revision into expense_rev from pro_expense_state where user_id=p_user for update;
  if expense_rev<>(p_input->>'expenseRevision')::bigint then raise exception 'Expenses changed' using errcode='40001';end if;
  if act='create_expense' then
   if jsonb_typeof(p_input->'supplierId') is distinct from 'string' or jsonb_typeof(p_input->'concept') is distinct from 'string' or length(btrim(p_input->>'concept')) not between 1 and 300 or jsonb_typeof(p_input->'amountCents') is distinct from 'number' or (p_input->>'amountCents')!~'^[0-9]{1,11}$' or (p_input->>'amountCents')::bigint not between 1 and 10000000000 or exists(select 1 from pro_internal_expenses where user_id=p_user and id=eid) then raise exception 'Invalid new expense' using errcode='22023';end if;
   expense_result:=pro_expenses_save(p_user,jsonb_build_object('action','expense','id',eid,'supplierId',p_input->>'supplierId','date',dt,'dueDate',null,'currency','CRC','concept',btrim(p_input->>'concept'),'amountCents',(p_input->>'amountCents')::bigint,'actionId',rid,'revision',expense_rev));
   expense_rev:=(expense_result->>'revision')::bigint;
  end if;
  select * into expense from pro_internal_expenses where user_id=p_user and id=eid for update;
  if not found then raise exception 'Invalid expense' using errcode='22023';end if;
  insert into pro_work_cost_entries(user_id,id,work_id,kind,recorded_on,amount_cents,note,expense_id,supplier_name) values(p_user,rid,wid,'expense',expense.expense_date,expense.amount_cents,expense.concept,eid,expense.supplier_name);
  insert into pro_work_expense_assignments(user_id,expense_id,work_id,entry_id) values(p_user,eid,wid,rid);
 end if;
 update pro_work_cost_state set revision=current_rev+1 where user_id=p_user;
 result:=jsonb_build_object('id',rid,'revision',current_rev+1,'expenseRevision',coalesce((select revision from pro_expense_state where user_id=p_user),0));
 insert into pro_work_cost_requests(user_id,request_id,input,result) values(p_user,rid,p_input,result);
 return result;
end $$;
create or replace function public.pro_work_costs_read(p_user uuid,p_client text,p_work text,p_kind text default 'entries',p_search text default '',p_after jsonb default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb;account jsonb;context jsonb;rev bigint;expense_rev bigint;labor bigint;material bigint;extras bigint;minutes_total bigint;unknown_minutes bigint;unknown_count bigint;agreed bigint;rows jsonb;fingerprint text;agreed_tax bigint;agreed_net bigint;committed bigint;
begin
 if p_user is null or p_client is null or p_work is null or length(p_client) not between 1 and 160 or length(p_work) not between 1 and 160 or p_kind is null or p_kind not in ('entries','candidates') or p_search is null or length(p_search)>160 then raise exception 'Invalid query' using errcode='22023';end if;
 select jsonb_build_object('id',w.id,'clientId',w."clientId",'title',w.service,'cancelled',w.cancelled,'clientArchived',c.archived) into context from pro_work w join pro_clients c on c.user_id=w.user_id and c.id=w."clientId" where w.user_id=p_user and w.id=p_work and c.id=p_client;
 if context is null then return null;end if;
 rev:=coalesce((select revision from pro_work_cost_state where user_id=p_user),0);expense_rev:=coalesce((select revision from pro_expense_state where user_id=p_user),0);
 if p_kind='candidates' then
  if p_after is not null and (jsonb_typeof(p_after) is distinct from 'object' or jsonb_typeof(p_after->'id') is distinct from 'string' or (p_after-array['id'])<>'{}'::jsonb) then raise exception 'Invalid cursor' using errcode='22023';end if;
  with candidates as materialized(select e.* from pro_internal_expenses e where e.user_id=p_user and not exists(select 1 from pro_work_expense_assignments a where a.user_id=e.user_id and a.expense_id=e.id) and strpos(pro_catalog_search(e.concept||' '||e.supplier_name),pro_catalog_search(p_search))>0),matches as(select * from candidates where p_after is null or id>(p_after->>'id')::uuid order by id limit 21),page as(select * from matches order by id limit 20)
  select jsonb_build_object('revision',rev,'expenseRevision',expense_rev,'fingerprint',md5(rev::text||expense_rev::text||coalesce((select jsonb_agg(jsonb_build_object('id',id,'amount',amount_cents,'concept',concept,'date',expense_date,'supplier',supplier_name) order by id)::text from candidates),'[]')),'items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'concept',concept,'supplierName',supplier_name,'date',expense_date,'amountCents',amount_cents) order by id) from page),'[]'),'nextCursor',case when(select count(*) from matches)>20 then(select jsonb_build_object('id',id) from page order by id desc limit 1) else null end) into result;
  return result;
 end if;
 if p_after is not null and (jsonb_typeof(p_after) is distinct from 'object' or jsonb_typeof(p_after->'position') is distinct from 'string' or (p_after->>'position')!~'^[0-9]{1,18}$' or (p_after-array['position'])<>'{}'::jsonb) then raise exception 'Invalid cursor' using errcode='22023';end if;
 account:=pro_work_account(p_user,p_work);agreed:=(account->>'agreedCents')::bigint;material:=round((account->>'materialCost')::numeric*100)::bigint;
 select coalesce(sum(e.minutes),0),coalesce(sum(e.minutes) filter(where e.hourly_cost_cents is null),0),count(*) filter(where e.hourly_cost_cents is null),coalesce(sum(e.amount_cents),0) into minutes_total,unknown_minutes,unknown_count,labor from pro_work_cost_entries e where e.user_id=p_user and e.work_id=p_work and e.kind='time' and not exists(select 1 from pro_work_cost_entries r where r.user_id=e.user_id and r.reversal_id=e.id);
 select coalesce(sum(e.amount_cents),0) into extras from pro_work_expense_assignments a join pro_internal_expenses e on e.user_id=a.user_id and e.id=a.expense_id where a.user_id=p_user and a.work_id=p_work;
 -- Round 1 (2026-11-12): same base. When the agreed amount comes from the accepted estimate its
 -- tax is known and the result uses the amount WITHOUT tax (costs are recorded without tax);
 -- otherwise the result says it compares the amount as agreed. Purchase orders not cancelled
 -- are a separate committed line (subtotal without tax), never mixed into recorded costs.
 agreed_tax:=(account->>'agreedTaxCents')::bigint;agreed_net:=case when agreed is null then null else agreed-coalesce(agreed_tax,0) end;
 begin
  select coalesce(sum(l.subtotal_cents),0)::bigint into committed from pro_purchase_order_lines l join pro_purchase_orders o on o.owner_id=l.owner_id and o.id=l.order_id where l.owner_id=p_user and l.work_id=p_work and o.status<>'cancelled';
 exception when undefined_table then committed:=0;end;
 with events as materialized(
  select e.position,jsonb_build_object('id',e.id,'kind',e.kind,'date',case when a.entry_id=e.id then x.expense_date else e.recorded_on end,'minutes',e.minutes,'hourlyCostCents',e.hourly_cost_cents,'amountCents',case when a.entry_id=e.id then x.amount_cents else e.amount_cents end,'note',case when a.entry_id=e.id then x.concept else e.note end,'expenseId',e.expense_id,'supplierName',case when a.entry_id=e.id then x.supplier_name else e.supplier_name end,'reversalId',e.reversal_id,'reversed',exists(select 1 from pro_work_cost_entries r where r.user_id=e.user_id and r.reversal_id=e.id),'at',e.created_at) row
  from pro_work_cost_entries e left join pro_work_expense_assignments a on a.user_id=e.user_id and a.expense_id=e.expense_id and a.entry_id=e.id left join pro_internal_expenses x on x.user_id=a.user_id and x.id=a.expense_id where e.user_id=p_user and e.work_id=p_work
 ),matches as(select * from events where p_after is null or position<(p_after->>'position')::bigint order by position desc limit 21),page as(select * from matches order by position desc limit 20)
 select jsonb_build_object('revision',rev,'expenseRevision',expense_rev,'fingerprint',md5(context::text||account::text||rev::text||coalesce((select jsonb_agg(row order by position)::text from events),'[]')),'work',context,'summary',jsonb_build_object('minutes',minutes_total,'uncostedMinutes',unknown_minutes,'uncostedCount',unknown_count,'laborCents',labor,'materialCents',material,'expensesCents',extras,'totalCostCents',labor+material+extras,'agreedCents',agreed,'agreedSource',account->'agreedSource','agreedTaxCents',agreed_tax,'agreedNetCents',agreed_net,'resultBasis',case when agreed_tax is not null then 'without_tax' else 'as_agreed' end,'committedCents',committed,'resultCents',case when agreed is null or unknown_count>0 then null else agreed_net-labor-material-extras end,'resultWithCommittedCents',case when agreed is null or unknown_count>0 then null else agreed_net-labor-material-extras-committed end),'items',coalesce((select jsonb_agg(row order by position desc) from page),'[]'),'nextCursor',case when(select count(*) from matches)>20 then(select jsonb_build_object('position',position::text) from page order by position limit 1) else null end) into result;
 return result;
end $$;
create or replace function public.pro_protect_work_cost_history() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (new.user_id,new.id,new."clientId") is distinct from (old.user_id,old.id,old."clientId") and exists(select 1 from pro_work_cost_entries where user_id=old.user_id and work_id=old.id) then raise exception 'Job cost history cannot change owner or client' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_protect_work_cost_history on public.pro_work;
create trigger pro_protect_work_cost_history before update on public.pro_work for each row execute function public.pro_protect_work_cost_history();
revoke all on function public.pro_protect_work_cost_history() from public,anon,authenticated;
grant execute on function public.pro_protect_work_cost_history() to service_role;
do $$declare n text;begin foreach n in array array['pro_work_cost_state','pro_work_cost_entries','pro_work_expense_assignments','pro_work_cost_requests'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant select on public.%I to authenticated',n);execute format('grant all on public.%I to service_role',n);
 if not exists(select 1 from pg_policies where schemaname='public' and tablename=n and policyname=n||'_owner') then execute format('create policy %I on public.%I for select to authenticated using(user_id=(select auth.uid()))',n||'_owner',n);end if;
 end loop;end $$;
grant usage,select on sequence public.pro_work_cost_entries_position_seq to service_role;
revoke all on function public.pro_work_costs_mutate(uuid,jsonb),public.pro_work_costs_read(uuid,text,text,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.pro_work_costs_mutate(uuid,jsonb),public.pro_work_costs_read(uuid,text,text,text,text,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== identity-lookup-local.sql =====
-- LOCAL PRO ONLY. Quotas contain opaque tokens, never identifications or names.
begin;
create table if not exists public.pro_identity_quota (
 key text primary key, hits integer not null check(hits>0), expires_at timestamptz not null
);
create index if not exists pro_identity_quota_expiry on public.pro_identity_quota(expires_at);
alter table public.pro_identity_quota enable row level security;
revoke all on public.pro_identity_quota from public,anon,authenticated;
grant select,insert,update,delete on public.pro_identity_quota to service_role;
create or replace function public.pro_identity_quota_take(p_account text,p_ip text)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare at_time timestamptz:=clock_timestamp(); keys text[]; ends timestamptz[]; limits integer[]:=array[20,60,100,5]; idx integer; existing public.pro_identity_quota;
begin
 if p_account is null or p_ip is null or p_account !~ '^[a-f0-9]{64}$' or p_ip !~ '^[a-f0-9]{64}$' then raise exception 'Invalid quota token' using errcode='22023';end if;
 -- One atomic decision across instances and all scopes. Denials do not consume other scopes.
 perform pg_advisory_xact_lock(6845211301);
 at_time:=clock_timestamp();
 delete from public.pro_identity_quota where expires_at<=at_time;
 keys:=array['account:'||p_account,'ip:'||p_ip,'global:minute','global:second'];
 ends:=array[at_time+interval '10 minutes',at_time+interval '10 minutes',at_time+interval '1 minute',at_time+interval '1 second'];
 for idx in 1..4 loop
  select * into existing from public.pro_identity_quota where key=keys[idx];
  if found and existing.hits>=limits[idx] then return jsonb_build_object('allowed',false,'retryAfter',greatest(1,ceil(extract(epoch from existing.expires_at-at_time))::integer));end if;
 end loop;
 for idx in 1..4 loop
  insert into public.pro_identity_quota(key,hits,expires_at) values(keys[idx],1,ends[idx])
  on conflict(key) do update set hits=pro_identity_quota.hits+1;
 end loop;
 return jsonb_build_object('allowed',true);
end $$;
revoke all on function public.pro_identity_quota_take(text,text) from public,anon,authenticated;
grant execute on function public.pro_identity_quota_take(text,text) to service_role;
-- Scheduled physical deletion is installed separately in the loopback preparation.
create or replace function public.pro_identity_quota_prune() returns void
language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pg_advisory_xact_lock(6845211301);delete from public.pro_identity_quota where expires_at<=clock_timestamp();end$$;
revoke all on function public.pro_identity_quota_prune() from public,anon,authenticated;
grant execute on function public.pro_identity_quota_prune() to service_role;
commit;

-- ===== identity-lookup-maintenance-local.sql =====
-- LOOPBACK ONLY via prepare-supabase-local. Never schedule hosted jobs from this draft.
create extension if not exists pg_cron;
select cron.schedule('pro-identity-quota-prune','* * * * *','select public.pro_identity_quota_prune()');

-- ===== visit-preparation-local.sql =====
-- LOCAL PRO ONLY. Additive preparation snapshots and explicit scheduling preferences.
begin;
create table if not exists public.pro_visit_settings(
 owner_id uuid primary key references profiles(id) on delete cascade,
 revision integer not null default 0 check(revision>=0),
 buffer_minutes integer not null default 0 check(buffer_minutes between 0 and 180 and buffer_minutes%15=0),
 notice_minutes integer not null default 15 check(notice_minutes between 15 and 10080 and notice_minutes%15=0),
 questions jsonb not null default '[]' check(jsonb_typeof(questions)='array' and jsonb_array_length(questions)<=3)
);
create table if not exists public.pro_visit_preparation(
 request_id uuid primary key references pro_appointment_requests(id) on delete cascade,
 questions jsonb not null default '[]',policy_revision integer not null,
 revision integer not null default 0,answers jsonb not null default '[]',updated_at timestamptz not null default now()
);
create table if not exists public.pro_visit_preparation_events(
 request_id uuid not null references pro_appointment_requests(id) on delete cascade,revision integer not null,
 answers jsonb not null,at timestamptz not null default now(),primary key(request_id,revision)
);
create table if not exists public.pro_visit_actions(
 actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,
 scope text not null,input jsonb not null,result jsonb not null,primary key(actor_id,action_id)
);
create or replace function public.pro_visit_snapshot() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare q jsonb;rev integer;
begin
 select revision,coalesce((select jsonb_agg(item order by n) from jsonb_array_elements(s.questions) with ordinality x(item,n) where btrim(item->>'service')='' or lower(btrim(item->>'service'))=lower(btrim(new.service))),'[]') into rev,q from pro_visit_settings s where owner_id=new.owner_id;
 insert into pro_visit_preparation(request_id,questions,policy_revision) values(new.id,coalesce(q,'[]'),coalesce(rev,0));return new;
end $$;
drop trigger if exists pro_visit_snapshot on public.pro_appointment_requests;
create trigger pro_visit_snapshot after insert on public.pro_appointment_requests for each row execute function public.pro_visit_snapshot();
create or replace function public.pro_visit_required() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if new.status='confirmed' and old.status<>'confirmed' and exists(select 1 from pro_visit_preparation p cross join lateral jsonb_array_elements(p.questions) q where p.request_id=new.id and coalesce((q->>'required')::boolean,false) and not exists(select 1 from jsonb_array_elements(p.answers) a where a->>'id'=q->>'id' and btrim(a->>'value')<>'')) then raise exception 'Complete required preparation answers before confirming' using errcode='23514';end if;return new;
end $$;
drop trigger if exists pro_visit_required on public.pro_appointment_requests;
create trigger pro_visit_required before update of status on public.pro_appointment_requests for each row execute function public.pro_visit_required();
create or replace function public.pro_visit_settings_record(p_actor uuid,p_input jsonb default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare s pro_visit_settings;prior pro_visit_actions;result jsonb;q jsonb;aid uuid;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) or not pro_appointment_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 select * into s from pro_visit_settings where owner_id=p_actor;
 if p_input is not null then
  if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]+$' then raise exception 'Invalid operation' using errcode='22023';end if;
  aid:=(p_input->>'actionId')::uuid;select * into prior from pro_visit_actions where actor_id=p_actor and action_id=aid;
  if found then if prior.scope<>'settings' or prior.input is distinct from p_input then raise exception 'Changed retry' using errcode='22023';end if;return prior.result;end if;
  if not(p_input ?& array['revision','bufferMinutes','noticeMinutes','questions','action','actionId']) or p_input->>'action'<>'settings' or (select count(*) from jsonb_object_keys(p_input))<>6 or jsonb_typeof(p_input->'bufferMinutes') is distinct from 'number' or jsonb_typeof(p_input->'noticeMinutes') is distinct from 'number' or (p_input->>'bufferMinutes')!~'^[0-9]+$' or (p_input->>'noticeMinutes')!~'^[0-9]+$' or jsonb_typeof(p_input->'questions') is distinct from 'array' or jsonb_array_length(p_input->'questions')>3 or (p_input->>'revision')::integer<>coalesce(s.revision,0) then raise exception 'Settings changed' using errcode='40001';end if;
  if (p_input->>'bufferMinutes')::integer not between 0 and 180 or (p_input->>'bufferMinutes')::integer%15<>0 or (p_input->>'noticeMinutes')::integer not between 15 and 10080 or (p_input->>'noticeMinutes')::integer%15<>0 then raise exception 'Invalid scheduling preference' using errcode='22023';end if;
  for q in select value from jsonb_array_elements(p_input->'questions') loop
   if not(q ?& array['id','label','service','required']) or (select count(*) from jsonb_object_keys(q))<>4 or jsonb_typeof(q->'required') is distinct from 'boolean' or jsonb_typeof(q->'label') is distinct from 'string' or jsonb_typeof(q->'service') is distinct from 'string' or jsonb_typeof(q->'id') is distinct from 'string' or length(btrim(q->>'label')) not between 1 and 160 or length(q->>'service')>160 or (q->>'id')::uuid is null then raise exception 'Invalid question' using errcode='22023';end if;
  end loop;
  if (select count(distinct value->>'id') from jsonb_array_elements(p_input->'questions'))<>jsonb_array_length(p_input->'questions') then raise exception 'Duplicate question' using errcode='22023';end if;
  insert into pro_visit_settings(owner_id,revision,buffer_minutes,notice_minutes,questions) values(p_actor,coalesce(s.revision,0)+1,(p_input->>'bufferMinutes')::integer,(p_input->>'noticeMinutes')::integer,p_input->'questions') on conflict(owner_id) do update set revision=excluded.revision,buffer_minutes=excluded.buffer_minutes,notice_minutes=excluded.notice_minutes,questions=excluded.questions returning * into s;
 end if;
 result:=jsonb_build_object('revision',coalesce(s.revision,0),'bufferMinutes',coalesce(s.buffer_minutes,0),'noticeMinutes',coalesce(s.notice_minutes,15),'questions',coalesce(s.questions,'[]'));
 if p_input is not null then insert into pro_visit_actions values(p_actor,aid,'settings',p_input,result);end if;return result;
end $$;
create or replace function public.pro_visit_preparation_record(p_actor uuid,p_id uuid,p_input jsonb default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r pro_appointment_requests;p pro_visit_preparation;owner uuid;prior pro_visit_actions;result jsonb;a jsonb;aid uuid;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id into owner from pro_appointment_requests where id=p_id and p_actor in(owner_id,client_user_id);if not found then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(owner::text,0));select * into r from pro_appointment_requests where id=p_id for update;
 select * into p from pro_visit_preparation where request_id=p_id for update;
 if p_input is not null then
  if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]+$' then raise exception 'Invalid operation' using errcode='22023';end if;
  aid:=(p_input->>'actionId')::uuid;select * into prior from pro_visit_actions where actor_id=p_actor and action_id=aid;
  if found then if prior.scope<>p_id::text or prior.input is distinct from p_input then raise exception 'Changed retry' using errcode='22023';end if;return prior.result;end if;
  if p_actor<>r.client_user_id or r.status not in('requested','proposed') then raise exception 'Preparation is read only' using errcode='42501';end if;
  if not(p_input ?& array['action','requestId','actionId','revision','answers']) or p_input->>'action'<>'answers' or (p_input->>'requestId')::uuid<>p_id or (select count(*) from jsonb_object_keys(p_input))<>5 or jsonb_typeof(p_input->'answers') is distinct from 'array' or jsonb_array_length(p_input->'answers')>3 then raise exception 'Invalid answers' using errcode='22023';end if;
  if (p_input->>'revision')::integer<>coalesce(p.revision,0) then raise exception 'Preparation changed' using errcode='40001';end if;
  for a in select value from jsonb_array_elements(p_input->'answers') loop
   if (select count(*) from jsonb_object_keys(a))<>2 or not(a ?& array['id','value']) or jsonb_typeof(a->'id') is distinct from 'string' or jsonb_typeof(a->'value') is distinct from 'string' or length(a->>'value')>500 or not exists(select 1 from jsonb_array_elements(coalesce(p.questions,'[]')) q where q->>'id'=a->>'id') then raise exception 'Invalid answer' using errcode='22023';end if;
  end loop;
  if (select count(distinct value->>'id') from jsonb_array_elements(p_input->'answers'))<>jsonb_array_length(p_input->'answers') then raise exception 'Duplicate answer' using errcode='22023';end if;
  insert into pro_visit_preparation(request_id,questions,policy_revision,revision,answers) values(p_id,'[]',0,1,p_input->'answers') on conflict(request_id) do update set revision=pro_visit_preparation.revision+1,answers=excluded.answers,updated_at=now() returning * into p;
  insert into pro_visit_preparation_events values(p_id,p.revision,p.answers,now());
  update pro_appointment_requests set revision=revision+1,updated_at=now() where id=p_id returning * into r;
 end if;
 result:=jsonb_build_object('requestId',p_id,'requestRevision',r.revision,'revision',coalesce(p.revision,0),'questions',coalesce(p.questions,'[]'),'answers',coalesce(p.answers,'[]'),'editable',p_actor=r.client_user_id and r.status in('requested','proposed'),'side',case when p_actor=r.owner_id then 'provider' else 'client' end,'history',coalesce((select jsonb_agg(jsonb_build_object('revision',e.revision,'at',e.at,'answers',e.answers) order by e.revision desc) from (select * from pro_visit_preparation_events where request_id=p_id order by revision desc limit 20)e),'[]'));
 if p_input is not null then insert into pro_visit_actions values(p_actor,aid,p_id::text,p_input,result);end if;return result;
end $$;
-- Applies to new automatic requests/acceptance. Defaults retain the earlier behavior.
create or replace function public.pro_appointment_slot_free(p_owner uuid,p_start timestamptz,p_duration integer) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(p_start>now()+make_interval(mins=>coalesce(s.notice_minutes,15)) and p_start<now()+interval '90 days'
 and p_duration between 15 and 480 and p_duration%15=0
 and extract(second from p_start)=0 and extract(minute from p_start)::integer%15=0
 and exists(select 1 from pro_availability a where a.user_id=p_owner and pro_instant(a.start)<=p_start and pro_instant(a."end")>=p_start+make_interval(mins=>p_duration))
 and not exists(select 1 from pro_work w where w.user_id=p_owner and not w.cancelled and pro_instant(w.start)<p_start+make_interval(mins=>p_duration+coalesce(s.buffer_minutes,0)) and pro_instant(w."end")>p_start-make_interval(mins=>coalesce(s.buffer_minutes,0))),false)
 from (select 1) anchor left join pro_visit_settings s on s.owner_id=p_owner;
$$;
create or replace function public.pro_visit_work_buffer() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare gap integer;notice integer;prior pro_work;
begin
 perform pg_advisory_xact_lock(hashtextextended(new.user_id::text,0));
 -- BEFORE INSERT runs for an upsert too. Metadata updates must not revalidate old appointments.
 if tg_op='INSERT' then
  select * into prior from pro_work where user_id=new.user_id and id=new.id;
  if found and new.start is not distinct from prior.start and new."end" is not distinct from prior."end" and new.cancelled is not distinct from prior.cancelled then return new;end if;
 end if;
 if tg_op='UPDATE' and new.start is not distinct from old.start and new."end" is not distinct from old."end" and new.cancelled is not distinct from old.cancelled then return new;end if;
 if new.cancelled or pro_instant(new.start)<=now() then return new;end if;
 select buffer_minutes,notice_minutes into gap,notice from pro_visit_settings where owner_id=new.user_id;
 if coalesce(gap,0)>0 and exists(select 1 from pro_work w where w.user_id=new.user_id and w.id<>new.id and not w.cancelled and pro_instant(w.start)<pro_instant(new."end")+make_interval(mins=>gap) and pro_instant(w."end")>pro_instant(new.start)-make_interval(mins=>gap)) then raise exception 'Leave the configured time between visits' using errcode='23514';end if;
 if new."bookingClientId" is not null and coalesce(notice,15)>15 and pro_instant(new.start)<=now()+make_interval(mins=>notice) then raise exception 'Respect the configured advance notice' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_visit_work_buffer on public.pro_work;
create trigger pro_visit_work_buffer before insert or update on public.pro_work for each row execute function public.pro_visit_work_buffer();
alter table pro_visit_settings enable row level security;
alter table pro_visit_preparation enable row level security;
alter table pro_visit_preparation_events enable row level security;
alter table pro_visit_actions enable row level security;
revoke all on pro_visit_settings,pro_visit_preparation,pro_visit_preparation_events,pro_visit_actions from anon,authenticated;
grant all on pro_visit_settings,pro_visit_preparation,pro_visit_preparation_events,pro_visit_actions to service_role;
revoke all on function pro_visit_snapshot(),pro_visit_required(),pro_visit_work_buffer(),pro_visit_settings_record(uuid,jsonb),pro_visit_preparation_record(uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_visit_settings_record(uuid,jsonb),pro_visit_preparation_record(uuid,uuid,jsonb) to service_role;
commit;

-- ===== work-delivery-local.sql =====
-- Pro local only. Additive private draft + immutable explicitly shared work report.
begin;
create table if not exists public.pro_work_delivery_drafts(
 owner_id uuid not null references public.profiles(id) on delete cascade,work_id text not null,
 revision integer not null default 0 check(revision>=0),content jsonb not null default '{"summary":"","checklist":[],"recommendations":"","photoIds":[]}',
 internal_note text not null default '' check(length(internal_note)<=2000),updated_at timestamptz not null default now(),
 primary key(owner_id,work_id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create table if not exists public.pro_work_delivery_photos(
 id uuid primary key,owner_id uuid not null references public.profiles(id) on delete cascade,work_id text not null,
 object_path text not null unique,name text not null check(length(name) between 1 and 160),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),
 size_bytes integer not null check(size_bytes between 1 and 2097152),ready boolean not null default false,created_at timestamptz not null default now(),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create table if not exists public.pro_work_delivery_versions(
 owner_id uuid not null,work_id text not null,version integer not null check(version>0),client_user_id uuid not null references public.profiles(id) on delete cascade,
 content jsonb not null,service text not null,completed_at text not null,published_at timestamptz not null default now(),acknowledged_at timestamptz,
 primary key(owner_id,work_id,version),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create table if not exists public.pro_work_delivery_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);
create index if not exists pro_work_delivery_client on public.pro_work_delivery_versions(client_user_id,owner_id,work_id,version desc);
create or replace function public.pro_work_delivery_read(p_actor uuid,p_work text default null,p_request uuid default null,p_after integer default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;d pro_work_delivery_drafts;items jsonb;photos jsonb;next_key integer;is_owner boolean;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_request is not null then select owner_id,work_id into owner,wid from pro_appointment_requests where id=p_request and p_actor in(owner_id,client_user_id) and work_id is not null;
 else owner:=p_actor;wid:=p_work;end if;
 if owner is null or wid is null or not exists(select 1 from pro_work where user_id=owner and id=wid) then return null;end if;
 is_owner:=owner=p_actor;
 select * into d from pro_work_delivery_drafts where owner_id=owner and work_id=wid;
 select coalesce(jsonb_agg(to_jsonb(v)-'owner_id'-'work_id'-'client_user_id' order by version desc),'[]') into items from (
 select version,content,service,completed_at as "completedAt",published_at as "publishedAt",acknowledged_at as "acknowledgedAt"
 from pro_work_delivery_versions where owner_id=owner and work_id=wid and (is_owner or client_user_id=p_actor) and (p_after is null or version<p_after) order by version desc limit 20) v;
 if jsonb_array_length(items)=20 and exists(select 1 from pro_work_delivery_versions where owner_id=owner and work_id=wid and (is_owner or client_user_id=p_actor) and version<(items->19->>'version')::integer) then next_key:=(items->19->>'version')::integer;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'ready',p.ready) order by p.created_at),'[]') into photos from pro_work_delivery_photos p where p.owner_id=owner and p.work_id=wid and (is_owner or p.ready and exists(select 1 from pro_work_delivery_versions v where v.owner_id=owner and v.work_id=wid and v.client_user_id=p_actor and v.content->'photoIds' ? p.id::text));
 return jsonb_build_object('side',case when is_owner then 'provider' else 'client' end,'workId',wid,'canPublish',is_owner and exists(select 1 from pro_work w join pro_appointment_requests r on r.owner_id=w.user_id and r.work_id=w.id where w.user_id=owner and w.id=wid and w.stage='completed' and not w.cancelled),'revision',case when is_owner then coalesce(d.revision,0) else 0 end,'draft',case when is_owner then coalesce(d.content,'{"summary":"","checklist":[],"recommendations":"","photoIds":[]}') else null end,'internalNote',case when is_owner then coalesce(d.internal_note,'') else null end,'photos',photos,'versions',items,'nextCursor',next_key);
end $$;
create or replace function public.pro_work_delivery_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid:=(p_input->>'actionId')::uuid;wid text:=p_input->>'workId';owner uuid:=p_actor;prior pro_work_delivery_actions;d pro_work_delivery_drafts;w pro_work;client uuid;v integer;result jsonb;c jsonb;keys text[];photo pro_work_delivery_photos;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or aid is null or act is null then raise exception 'Invalid input' using errcode='22023';end if;
 if act='acknowledge' then select owner_id,work_id into owner,wid from pro_appointment_requests where id=(p_input->>'requestId')::uuid and client_user_id=p_actor and work_id is not null;end if;
 if owner is null or wid is null then raise exception 'Unavailable' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(owner::text,0));
 select * into prior from pro_work_delivery_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Changed retry' using errcode='22023';end if;return prior.result;end if;
 select * into w from pro_work where user_id=owner and id=wid;if not found then raise exception 'Unavailable' using errcode='42501';end if;
 if act='acknowledge' then
  select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;if keys<>array['action','actionId','requestId','version'] then raise exception 'Invalid input' using errcode='22023';end if;
  update pro_work_delivery_versions set acknowledged_at=coalesce(acknowledged_at,now()) where owner_id=owner and work_id=wid and version=(p_input->>'version')::integer and client_user_id=p_actor;
  if not found then raise exception 'Version unavailable' using errcode='42501';end if;result:=jsonb_build_object('workId',wid,'version',(p_input->>'version')::integer,'acknowledged',true);
 else
  if not pro_appointment_enabled(owner) then raise exception 'Pro required' using errcode='42501';end if;
  insert into pro_work_delivery_drafts(owner_id,work_id) values(owner,wid) on conflict do nothing;
  select * into d from pro_work_delivery_drafts where owner_id=owner and work_id=wid for update;
  if act='photo' then
   select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;if keys<>array['action','actionId','name','sha256','sizeBytes','workId'] then raise exception 'Invalid photo' using errcode='22023';end if;
   if (select count(*) from pro_work_delivery_photos where owner_id=owner and work_id=wid)>=6 then raise exception 'Photo limit' using errcode='54000';end if;
   insert into pro_work_delivery_photos(id,owner_id,work_id,object_path,name,sha256,size_bytes) values(aid,owner,wid,owner::text||'/'||aid::text||'.jpg',p_input->>'name',p_input->>'sha256',(p_input->>'sizeBytes')::integer) returning * into photo;
   result:=jsonb_build_object('id',photo.id,'path',photo.object_path,'ready',photo.ready);
  else
   if jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]+$' then raise exception 'Invalid revision' using errcode='22023';end if;
   if d.revision<>(p_input->>'revision')::integer then raise exception 'Changed revision' using errcode='40001';end if;
   if act='save' then
    select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;if keys<>array['action','actionId','content','internalNote','revision','workId'] then raise exception 'Invalid save' using errcode='22023';end if;
    c:=p_input->'content';if jsonb_typeof(c)<>'object' or (select count(*) from jsonb_object_keys(c))<>4 or not(c ?& array['summary','checklist','recommendations','photoIds']) or jsonb_typeof(c->'summary')<>'string' or length(c->>'summary')>2000 or jsonb_typeof(c->'recommendations')<>'string' or length(c->>'recommendations')>2000 or jsonb_typeof(c->'checklist')<>'array' or jsonb_array_length(c->'checklist')>20 or jsonb_typeof(c->'photoIds')<>'array' or jsonb_array_length(c->'photoIds')>6 or jsonb_typeof(p_input->'internalNote')<>'string' or length(p_input->>'internalNote')>2000 then raise exception 'Invalid content' using errcode='22023';end if;
    if exists(select 1 from jsonb_array_elements(c->'checklist') e where jsonb_typeof(e)<>'object' or (select count(*) from jsonb_object_keys(e))<>2 or not(e ?& array['label','done']) or jsonb_typeof(e->'label') is distinct from 'string' or length(btrim(e->>'label')) not between 1 and 160 or jsonb_typeof(e->'done')<>'boolean') then raise exception 'Invalid checklist' using errcode='22023';end if;
    if exists(select 1 from jsonb_array_elements_text(c->'photoIds') x(value) where not exists(select 1 from pro_work_delivery_photos p where p.id::text=x.value and p.owner_id=owner and p.work_id=wid and p.ready)) or (select count(distinct x.value) from jsonb_array_elements_text(c->'photoIds') x(value))<>jsonb_array_length(c->'photoIds') then raise exception 'Invalid photos' using errcode='42501';end if;
    update pro_work_delivery_drafts set content=c,internal_note=p_input->>'internalNote',revision=revision+1,updated_at=now() where owner_id=owner and work_id=wid returning revision into v;
   elsif act='publish' then
    select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;if keys<>array['action','actionId','revision','workId'] then raise exception 'Invalid publish' using errcode='22023';end if;
    if w.stage<>'completed' or w.cancelled or length(btrim(d.content->>'summary'))=0 then raise exception 'Complete the job and report first' using errcode='22023';end if;
    select client_user_id into client from pro_appointment_requests where owner_id=owner and work_id=wid;
    if client is null then raise exception 'No linked client account' using errcode='42501';end if;
    select coalesce(max(version),0)+1 into v from pro_work_delivery_versions where owner_id=owner and work_id=wid;
    if v>100 then raise exception 'Version limit' using errcode='54000';end if;
    insert into pro_work_delivery_versions(owner_id,work_id,version,client_user_id,content,service,completed_at) values(owner,wid,v,client,d.content,w.service,w."end");
    update pro_work_delivery_drafts set revision=revision+1,updated_at=now() where owner_id=owner and work_id=wid returning revision into v;
   else raise exception 'Invalid operation' using errcode='22023';end if;
   result:=jsonb_build_object('workId',wid,'revision',v);
  end if;
 end if;
 insert into pro_work_delivery_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);return result;
end $$;
create or replace function public.pro_work_delivery_photo_ready(p_actor uuid,p_id uuid) returns boolean language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if not pro_appointment_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 update pro_work_delivery_photos set ready=true where id=p_id and owner_id=p_actor;return found;
end $$;
create or replace function public.pro_work_delivery_photo_path(p_actor uuid,p_id uuid) returns text language sql stable security invoker set search_path=public,pg_temp as $$
 select p.object_path from pro_work_delivery_photos p where p.id=p_id and p.ready and exists(select 1 from profiles a where a.id=p_actor and not coalesce(a.is_disabled,false)) and (p.owner_id=p_actor or exists(select 1 from pro_work_delivery_versions v where v.owner_id=p.owner_id and v.work_id=p.work_id and v.client_user_id=p_actor and v.content->'photoIds' ? p.id::text));
$$;
create or replace function public.pro_work_delivery_version_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (to_jsonb(new)-'acknowledged_at') is distinct from (to_jsonb(old)-'acknowledged_at') or old.acknowledged_at is not null and new.acknowledged_at is distinct from old.acknowledged_at then raise exception 'Published report is immutable' using errcode='23514';end if;return new;
end $$;
drop trigger if exists pro_work_delivery_version_guard on public.pro_work_delivery_versions;
create trigger pro_work_delivery_version_guard before update on public.pro_work_delivery_versions for each row execute function public.pro_work_delivery_version_guard();
revoke all on function public.pro_work_delivery_version_guard() from public,anon,authenticated;
alter table public.pro_work_delivery_drafts enable row level security;alter table public.pro_work_delivery_photos enable row level security;alter table public.pro_work_delivery_versions enable row level security;alter table public.pro_work_delivery_actions enable row level security;
revoke all on public.pro_work_delivery_drafts,public.pro_work_delivery_photos,public.pro_work_delivery_versions,public.pro_work_delivery_actions from anon,authenticated;
grant all on public.pro_work_delivery_drafts,public.pro_work_delivery_photos,public.pro_work_delivery_versions,public.pro_work_delivery_actions to service_role;
revoke all on function public.pro_work_delivery_read(uuid,text,uuid,integer),public.pro_work_delivery_mutate(uuid,jsonb),public.pro_work_delivery_photo_ready(uuid,uuid),public.pro_work_delivery_photo_path(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_work_delivery_read(uuid,text,uuid,integer),public.pro_work_delivery_mutate(uuid,jsonb),public.pro_work_delivery_photo_ready(uuid,uuid),public.pro_work_delivery_photo_path(uuid,uuid) to service_role;
do $$begin if to_regclass('storage.buckets') is not null then insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-work-delivery','pro-work-delivery',false,2097152,array['image/jpeg']) on conflict(id) do nothing;if exists(select 1 from storage.buckets where id='pro-work-delivery' and public) then raise exception 'Work delivery bucket must be private';end if;end if;end $$;
-- Restrictive policy protects this bucket even if another permissive storage policy is broad.
do $$begin if to_regclass('storage.objects') is not null then
 execute 'drop policy if exists pro_work_delivery_no_direct on storage.objects';
 execute 'create policy pro_work_delivery_no_direct on storage.objects as restrictive for all to anon,authenticated using (bucket_id <> ''pro-work-delivery'') with check (bucket_id <> ''pro-work-delivery'')';
end if;end $$;
commit;
